export const STRUCTURE_GENERATORS: Record<StructureKey,(bx:number,by:number,bz:number)=>BP[]> = {
  OAK_HOUSE: oakHouse, STONE_TOWER: stoneTower, DESERT_PYRAMID: desertPyramid,
  DESERT_WELL: desertWell, DUNGEON: dungeon, TAIGA_CABIN: taigaCabin,
  JUNGLE_TEMPLE: jungleTemple, SWAMP_HUT: swampHut, VILLAGE_WELL: villageWell,
  STONE_CIRCLE: stoneCircle, RUINED_TOWER: ruinedTower, IGLOO: igloo,
  BLACKSTONE_FORT: blackstonefort, MINE_ENTRANCE: mineEntrance, MESA_RUIN: mesaRuin,
  END_PORTAL_FRAG: endPortalFragment, MUSHROOM_HOLLOW: mushroomHollow, GRAVEYARD: graveyard,
  UNDERWATER_RUIN: underwaterRuin, MONOLITH: monolith, NETHER_SHRINE: netherShrine,
  BEACON_SHRINE: beaconShrine, ANCIENT_LIBRARY: ancientLibrary,
  OCEAN_MONUMENT: oceanMonument, OUTPOST_TOWER: outpostTower,
};

import { createNoise2D } from 'simplex-noise';
import { BlockType, isSolid } from './blocks';
import { Biome, BIOME_DEFS } from './biomes';
import { STRUCTURE_GENERATORS, StructureKey, BP } from './structures';

export const CHUNK_SIZE = 16;
export const WORLD_HEIGHT = 64;
export const SEA_LEVEL = 6;

export type ChunkData = Uint8Array;

export function getChunkKey(cx: number, cz: number): string { return `${cx},${cz}`; }
export function blockIndex(lx: number, y: number, lz: number): number {
  return lx + y * CHUNK_SIZE + lz * CHUNK_SIZE * WORLD_HEIGHT;
}

const terrainNoise = createNoise2D();
const terrainNoise2 = createNoise2D();
const terrainNoise3 = createNoise2D();
const biomeNoise    = createNoise2D();
const oreNoise      = createNoise2D();

function pseudoRand(seed: number): number {
  const s = Math.sin(seed * 7919.131 + 2147.483) * 43758.5453;
  return s - Math.floor(s);
}

function getBiome(wx: number, wz: number): Biome {
  const n = biomeNoise(wx * 0.003, wz * 0.003);
  return Math.min(9, Math.floor((n + 1) / 2 * 10)) as Biome;
}

function getTerrainHeightAtPoint(wx: number, wz: number, def: ReturnType<typeof BIOME_DEFS[Biome]>): number {
  const n1 = terrainNoise(wx * 0.012, wz * 0.012);
  const n2 = terrainNoise2(wx * 0.04, wz * 0.04) * 0.5;
  const n3 = terrainNoise3(wx * 0.09, wz * 0.09) * 0.25;
  return Math.floor(def.baseHeight + (n1 + n2 + n3) * def.heightVariation);
}

// Biome structures mapping
const BIOME_STRUCTURES: Record<Biome, StructureKey[]> = {
  [Biome.PLAINS]:    ['OAK_HOUSE','VILLAGE_WELL','STONE_CIRCLE','GRAVEYARD','OUTPOST_TOWER'],
  [Biome.FOREST]:    ['OAK_HOUSE','ANCIENT_LIBRARY','MUSHROOM_HOLLOW','RUINED_TOWER'],
  [Biome.DESERT]:    ['DESERT_PYRAMID','DESERT_WELL','MESA_RUIN'],
  [Biome.OCEAN]:     ['UNDERWATER_RUIN','OCEAN_MONUMENT'],
  [Biome.TAIGA]:     ['TAIGA_CABIN','IGLOO','OUTPOST_TOWER','STONE_CIRCLE'],
  [Biome.JUNGLE]:    ['JUNGLE_TEMPLE','MUSHROOM_HOLLOW','ANCIENT_LIBRARY'],
  [Biome.SAVANNA]:   ['OAK_HOUSE','OUTPOST_TOWER','GRAVEYARD','STONE_CIRCLE'],
  [Biome.SWAMP]:     ['SWAMP_HUT','GRAVEYARD','MUSHROOM_HOLLOW'],
  [Biome.MOUNTAINS]: ['STONE_TOWER','RUINED_TOWER','MONOLITH','BEACON_SHRINE'],
  [Biome.MESA]:      ['MESA_RUIN','STONE_CIRCLE','BLACKSTONE_FORT','NETHER_SHRINE'],
};

function generateChunk(cx: number, cz: number): ChunkData {
  const data = new Uint8Array(CHUNK_SIZE * WORLD_HEIGHT * CHUNK_SIZE);

  // Determine the dominant biome for this chunk (center point)
  const chunkCenterX = cx * CHUNK_SIZE + CHUNK_SIZE / 2;
  const chunkCenterZ = cz * CHUNK_SIZE + CHUNK_SIZE / 2;
  const chunkBiome = getBiome(chunkCenterX, chunkCenterZ);
  const def = BIOME_DEFS[chunkBiome];

  for (let lx = 0; lx < CHUNK_SIZE; lx++) {
    for (let lz = 0; lz < CHUNK_SIZE; lz++) {
      const wx = cx * CHUNK_SIZE + lx;
      const wz = cz * CHUNK_SIZE + lz;
      const biome = getBiome(wx, wz);
      const bd = BIOME_DEFS[biome];
      const height = Math.max(1, getTerrainHeightAtPoint(wx, wz, bd));

      for (let y = 0; y < WORLD_HEIGHT; y++) {
        const idx = blockIndex(lx, y, lz);
        if (y === 0) {
          data[idx] = BlockType.BEDROCK;
        } else if (y < height - 4) {
          // Ore generation
          const ore = oreNoise(wx * 0.25 + y * 0.7, wz * 0.25);
          if (y < 16 && ore > 0.72)       data[idx] = BlockType.COAL_ORE;
          else if (y < 30 && ore > 0.78)  data[idx] = BlockType.IRON_ORE;
          else if (y < 20 && ore > 0.82)  data[idx] = BlockType.GOLD_ORE;
          else if (y < 12 && ore > 0.86)  data[idx] = BlockType.DIAMOND_ORE;
          else if (y < 32 && ore > 0.84)  data[idx] = BlockType.COPPER_ORE;
          else if (y < 24 && ore > 0.88)  data[idx] = BlockType.EMERALD_ORE;
          else if (y < 16 && ore > 0.90)  data[idx] = BlockType.LAPIS_ORE;
          else if (y < 16 && ore > 0.92)  data[idx] = BlockType.REDSTONE_ORE;
          else if (y < 8)                 data[idx] = biome === Biome.MOUNTAINS ? BlockType.DEEPSLATE : BlockType.STONE;
          else                             data[idx] = BlockType.STONE;
        } else if (y < height) {
          data[idx] = bd.subSurfaceBlock;
        } else if (y === height) {
          if (biome === Biome.MOUNTAINS && height > 28) data[idx] = BlockType.SNOW_BLOCK;
          else if (biome === Biome.TAIGA && height > 22) data[idx] = BlockType.SNOW_BLOCK;
          else data[idx] = bd.surfaceBlock;
        } else if (y <= SEA_LEVEL) {
          data[idx] = biome === Biome.OCEAN ? BlockType.WATER : bd.seaFillBlock;
        } else {
          data[idx] = BlockType.AIR;
        }
      }

      // Tree generation
      if (bd.treeDensity > 0 && height > SEA_LEVEL && lx >= 2 && lx <= CHUNK_SIZE - 3 && lz >= 2 && lz <= CHUNK_SIZE - 3) {
        const treeRoll = pseudoRand(wx * 1234.567 + wz * 89.123);
        if (treeRoll < bd.treeDensity) {
          if (biome === Biome.DESERT) {
            // Cactus
            const cactusH = 2 + Math.floor(pseudoRand(wx + wz * 3) * 3);
            for (let ty = 1; ty <= cactusH; ty++) {
              const y = height + ty;
              if (y < WORLD_HEIGHT) data[blockIndex(lx, y, lz)] = BlockType.CACTUS;
            }
          } else {
            const trunkH = bd.treeTrunkMin + Math.floor(pseudoRand(wx * 3 + wz) * (bd.treeTrunkMax - bd.treeTrunkMin + 1));
            // Trunk
            for (let ty = 1; ty <= trunkH; ty++) {
              const y = height + ty;
              if (y < WORLD_HEIGHT) data[blockIndex(lx, y, lz)] = bd.treeLog;
            }
            // Leaves
            if (bd.treeLeafRadius > 0) {
              for (let ly = trunkH - 1; ly <= trunkH + 1; ly++) {
                const radius = ly <= trunkH ? bd.treeLeafRadius : Math.max(1, bd.treeLeafRadius - 1);
                for (let dx = -radius; dx <= radius; dx++) {
                  for (let dz2 = -radius; dz2 <= radius; dz2++) {
                    if (Math.abs(dx) === radius && Math.abs(dz2) === radius) continue;
                    const nlx = lx + dx; const nlz = lz + dz2;
                    const ny = height + ly;
                    if (nlx >= 0 && nlx < CHUNK_SIZE && nlz >= 0 && nlz < CHUNK_SIZE && ny < WORLD_HEIGHT) {
                      if (data[blockIndex(nlx, ny, nlz)] === BlockType.AIR) {
                        data[blockIndex(nlx, ny, nlz)] = bd.treeLeaf;
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }

  // Structure placement
  const structureRoll = pseudoRand(cx * 7919 + cz * 3571);
  if (structureRoll > 0.90) {
    const options = BIOME_STRUCTURES[chunkBiome];
    const sIdx = Math.floor(pseudoRand(cx * 13 + cz * 17) * options.length);
    const structureKey = options[sIdx];
    const generator = STRUCTURE_GENERATORS[structureKey];

    // Base position at chunk center surface
    const sCx = cx * CHUNK_SIZE + 4;
    const sCz = cz * CHUNK_SIZE + 4;
    // Find height at that point
    const sBiome = getBiome(sCx, sCz);
    const sDef = BIOME_DEFS[sBiome];
    const sH = getTerrainHeightAtPoint(sCx, sCz, sDef);

    // For dungeon: place underground
    const baseY = structureKey === 'DUNGEON' ? Math.max(5, sH - 8) : structureKey === 'UNDERWATER_RUIN' || structureKey === 'OCEAN_MONUMENT' ? Math.max(1, sH - 2) : sH;

    const placements: BP[] = generator(sCx, baseY, sCz);
    placements.forEach(([wx, wy, wz, type]) => {
      const lx = wx - cx * CHUNK_SIZE;
      const lz = wz - cz * CHUNK_SIZE;
      if (lx < 0 || lx >= CHUNK_SIZE || lz < 0 || lz >= CHUNK_SIZE) return;
      if (wy < 0 || wy >= WORLD_HEIGHT) return;
      data[blockIndex(lx, wy, lz)] = type;
    });
  }

  return data;
}

class WorldManager {
  chunks = new Map<string, ChunkData>();
  dirtyChunks = new Set<string>();

  getOrGenerateChunk(cx: number, cz: number): ChunkData {
    const key = getChunkKey(cx, cz);
    let chunk = this.chunks.get(key);
    if (!chunk) { chunk = generateChunk(cx, cz); this.chunks.set(key, chunk); }
    return chunk;
  }

  getBlock(x: number, y: number, z: number): BlockType {
    if (y < 0) return BlockType.BEDROCK;
    if (y >= WORLD_HEIGHT) return BlockType.AIR;
    const cx = Math.floor(x / CHUNK_SIZE);
    const cz = Math.floor(z / CHUNK_SIZE);
    const chunk = this.getOrGenerateChunk(cx, cz);
    const lx = ((x % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
    const lz = ((z % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
    return chunk[blockIndex(lx, y, lz)];
  }

  setBlock(x: number, y: number, z: number, type: BlockType): void {
    if (y < 0 || y >= WORLD_HEIGHT) return;
    const cx = Math.floor(x / CHUNK_SIZE);
    const cz = Math.floor(z / CHUNK_SIZE);
    const chunk = this.getOrGenerateChunk(cx, cz);
    const lx = ((x % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
    const lz = ((z % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
    chunk[blockIndex(lx, y, lz)] = type;
    this.dirtyChunks.add(getChunkKey(cx, cz));
    if (lx === 0) this.dirtyChunks.add(getChunkKey(cx-1, cz));
    if (lx === CHUNK_SIZE-1) this.dirtyChunks.add(getChunkKey(cx+1, cz));
    if (lz === 0) this.dirtyChunks.add(getChunkKey(cx, cz-1));
    if (lz === CHUNK_SIZE-1) this.dirtyChunks.add(getChunkKey(cx, cz+1));
  }

  getTerrainHeight(x: number, z: number): number {
    for (let y = WORLD_HEIGHT - 1; y >= 0; y--) {
      if (isSolid(this.getBlock(x, y, z))) return y;
    }
    return 0;
  }
}

export const worldManager = new WorldManager();

export type MobType = 'zombie' | 'skeleton' | 'spider' | 'creeper' | 'slime';

export interface MobState {
  id: number;
  type: MobType;
  pos: [number, number, number];
  vel: [number, number, number];
  yaw: number;
  health: number;
  maxHealth: number;
  state: 'idle' | 'patrol' | 'aggro' | 'attack' | 'dead';
  deathTimer: number;
  hitFlash: number;
  attackCooldown: number;
  patrolTimer: number;
  patrolDir: [number, number];
}

export interface MobSpec {
  h: number;   // height
  hw: number;  // half-width
  speed: number;
  aggroRange: number;
  attackRange: number;
  attackDamage: number;
  color: number;    // hex
  headColor: number;
  maxHealth: number;
}

export const MOB_SPECS: Record<MobType, MobSpec> = {
  zombie:   { h:1.9, hw:0.4, speed:0.03, aggroRange:16, attackRange:1.2, attackDamage:3, color:0x3a7a3a, headColor:0x4a9a4a, maxHealth:20 },
  skeleton: { h:1.9, hw:0.35, speed:0.04, aggroRange:20, attackRange:15, attackDamage:2, color:0xc8c8c8, headColor:0xdddddd, maxHealth:20 },
  spider:   { h:0.8, hw:0.7,  speed:0.07, aggroRange:14, attackRange:1.0, attackDamage:2, color:0x222222, headColor:0x882222, maxHealth:16 },
  creeper:  { h:1.7, hw:0.4,  speed:0.025,aggroRange:16, attackRange:2.0, attackDamage:10,color:0x44aa44, headColor:0x44aa44, maxHealth:20 },
  slime:    { h:1.0, hw:0.5,  speed:0.02, aggroRange:10, attackRange:1.2, attackDamage:2, color:0x60c840, headColor:0x60c840, maxHealth:8  },
};

const mobs: MobState[] = [];
let nextId = 0;

export function getMobs(): MobState[] { return mobs; }

export function spawnMob(type: MobType, x: number, y: number, z: number): void {
  const spec = MOB_SPECS[type];
  mobs.push({
    id: nextId++, type, pos:[x,y,z], vel:[0,0,0], yaw:Math.random()*Math.PI*2,
    health:spec.maxHealth, maxHealth:spec.maxHealth,
    state:'idle', deathTimer:0, hitFlash:0, attackCooldown:0,
    patrolTimer:0, patrolDir:[0,0],
  });
}

export function damageMob(id: number, amount: number): void {
  const mob = mobs.find(m => m.id === id);
  if (!mob || mob.state === 'dead') return;
  mob.health -= amount;
  mob.hitFlash = 0.25;
  if (mob.health <= 0) { mob.state = 'dead'; mob.deathTimer = 1.2; mob.health = 0; }
  else if (mob.state === 'idle' || mob.state === 'patrol') mob.state = 'aggro';
}

export function cleanDeadMobs(): void {
  for (let i = mobs.length - 1; i >= 0; i--) {
    if (mobs[i].state === 'dead' && mobs[i].deathTimer <= 0) mobs.splice(i, 1);
  }
}

export function raycastMobs(
  ox: number, oy: number, oz: number,
  dx: number, dy: number, dz: number,
  maxDist: number
): { id: number; dist: number } | null {
  let best: { id: number; dist: number } | null = null;
  for (const mob of mobs) {
    if (mob.state === 'dead') continue;
    const spec = MOB_SPECS[mob.type];
    const [mx,my,mz] = mob.pos;
    const dist = rayAABB(ox,oy,oz,dx,dy,dz, mx-spec.hw,my,mz-spec.hw, mx+spec.hw,my+spec.h,mz+spec.hw);
    if (dist !== null && dist <= maxDist && (!best || dist < best.dist)) best = { id: mob.id, dist };
  }
  return best;
}

function rayAABB(ox:number,oy:number,oz:number,dx:number,dy:number,dz:number,minX:number,minY:number,minZ:number,maxX:number,maxY:number,maxZ:number): number|null {
  let tmin=0, tmax=Infinity;
  const oArr=[ox,oy,oz], dArr=[dx,dy,dz], minArr=[minX,minY,minZ], maxArr=[maxX,maxY,maxZ];
  for(let i=0;i<3;i++){
    if(Math.abs(dArr[i])<1e-8){ if(oArr[i]<minArr[i]||oArr[i]>maxArr[i]) return null; }
    else {
      const t1=(minArr[i]-oArr[i])/dArr[i], t2=(maxArr[i]-oArr[i])/dArr[i];
      tmin=Math.max(tmin,Math.min(t1,t2)); tmax=Math.min(tmax,Math.max(t1,t2));
      if(tmin>tmax) return null;
    }
  }
  return tmin>=0?tmin:null;
}

import { useRef, useEffect } from 'react';

export interface TouchState {
  dx: number; dy: number; dz: number;
  jump: boolean; breakBlock: boolean; placeBlock: boolean;
  flyDown: boolean; toggleMode: boolean;
  lookDx: number; lookDy: number;
}

export function createTouchState(): TouchState {
  return { dx:0, dy:0, dz:0, jump:false, breakBlock:false, placeBlock:false, flyDown:false, toggleMode:false, lookDx:0, lookDy:0 };
}

const JOYSTICK_RADIUS = 50;

interface Props { stateRef: React.MutableRefObject<TouchState>; isMobile: boolean; }

export default function TouchControls({ stateRef, isMobile }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const joystickTouchId  = useRef<number | null>(null);
  const lookTouchId      = useRef<number | null>(null);
  const joyCenter        = useRef({ x: 0, y: 0 });
  const joyKnobRef       = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isMobile) return;
    const el = containerRef.current;
    if (!el) return;

    function getJoyPos(el: HTMLDivElement) {
      const r = el.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    }

    function onTouchStart(e: TouchEvent) {
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        const joyEl = (containerRef.current as HTMLDivElement).querySelector('.joy-zone') as HTMLDivElement;
        if (joyEl) {
          const r = joyEl.getBoundingClientRect();
          const inJoy = t.clientX >= r.left && t.clientX <= r.right && t.clientY >= r.top && t.clientY <= r.bottom;
          if (inJoy && joystickTouchId.current === null) {
            joystickTouchId.current = t.identifier;
            joyCenter.current = { x: t.clientX, y: t.clientY };
            continue;
          }
        }
        // Right side look zone (not buttons)
        if (t.clientX > window.innerWidth * 0.35 && lookTouchId.current === null) {
          // Check if NOT hitting a button
          const hit = document.elementFromPoint(t.clientX, t.clientY);
          if (hit && (hit as HTMLElement).dataset.btn) continue;
          lookTouchId.current = t.identifier;
        }
      }
    }

    function onTouchMove(e: TouchEvent) {
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        if (t.identifier === joystickTouchId.current) {
          const rawDx = t.clientX - joyCenter.current.x;
          const rawDy = t.clientY - joyCenter.current.y;
          const dist  = Math.sqrt(rawDx*rawDx + rawDy*rawDy);
          const clamped = Math.min(dist, JOYSTICK_RADIUS);
          const nx = dist > 0 ? (rawDx / dist) * (clamped / JOYSTICK_RADIUS) : 0;
          const ny = dist > 0 ? (rawDy / dist) * (clamped / JOYSTICK_RADIUS) : 0;
          stateRef.current.dx = nx;
          stateRef.current.dz = ny; // positive = joystick pushed down (= backward)
          if (joyKnobRef.current) {
            joyKnobRef.current.style.transform = `translate(${nx * JOYSTICK_RADIUS}px, ${ny * JOYSTICK_RADIUS}px)`;
          }
        } else if (t.identifier === lookTouchId.current) {
          // Accumulate look delta — Player.tsx reads+resets each frame
          const prevTouch = (lookTouchId as any).__prevX;
          if ((lookTouchId as any).__prevX !== undefined) {
            stateRef.current.lookDx += t.clientX - (lookTouchId as any).__prevX;
            stateRef.current.lookDy += t.clientY - (lookTouchId as any).__prevY;
          }
          (lookTouchId as any).__prevX = t.clientX;
          (lookTouchId as any).__prevY = t.clientY;
        }
      }
    }

    function onTouchEnd(e: TouchEvent) {
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        if (t.identifier === joystickTouchId.current) {
          joystickTouchId.current = null;
          stateRef.current.dx = 0; stateRef.current.dz = 0;
          if (joyKnobRef.current) joyKnobRef.current.style.transform = '';
        }
        if (t.identifier === lookTouchId.current) {
          lookTouchId.current = null;
          delete (lookTouchId as any).__prevX;
          delete (lookTouchId as any).__prevY;
        }
      }
    }

    el.addEventListener('touchstart', onTouchStart, { passive: true });
    el.addEventListener('touchmove', onTouchMove, { passive: true });
    el.addEventListener('touchend', onTouchEnd, { passive: true });
    el.addEventListener('touchcancel', onTouchEnd, { passive: true });
    return () => {
      el.removeEventListener('touchstart', onTouchStart);
      el.removeEventListener('touchmove', onTouchMove);
      el.removeEventListener('touchend', onTouchEnd);
      el.removeEventListener('touchcancel', onTouchEnd);
    };
  }, [isMobile, stateRef]);

  if (!isMobile) return null;

  const btn = (label: string, key: keyof TouchState, style?: React.CSSProperties) => ({
    onTouchStart: (e: React.TouchEvent) => {
      e.stopPropagation();
      (stateRef.current as any)[key] = true;
    },
    onTouchEnd: (e: React.TouchEvent) => {
      e.stopPropagation();
      if (key === 'jump' || key === 'flyDown' || key === 'breakBlock' || key === 'placeBlock') {
        (stateRef.current as any)[key] = false;
      }
    },
    'data-btn': '1',
    style: {
      width:60, height:60, borderRadius:'50%', border:'2px solid rgba(255,255,255,0.5)',
      background:'rgba(0,0,0,0.4)', color:'#fff', fontSize:11, fontWeight:700,
      display:'flex', alignItems:'center', justifyContent:'center',
      touchAction:'none', userSelect:'none' as const,
      ...style,
    },
  });

  return (
    <div
      ref={containerRef}
      style={{ position:'fixed', inset:0, pointerEvents:'none', zIndex:10 }}
    >
      {/* Joystick zone (bottom-left) */}
      <div className="joy-zone" style={{
        position:'absolute', bottom:20, left:20,
        width:130, height:130, borderRadius:'50%',
        background:'rgba(255,255,255,0.08)',
        border:'2px solid rgba(255,255,255,0.25)',
        display:'flex', alignItems:'center', justifyContent:'center',
        pointerEvents:'auto', touchAction:'none',
      }}>
        <div ref={joyKnobRef} style={{
          width:52, height:52, borderRadius:'50%',
          background:'rgba(255,255,255,0.35)',
          border:'2px solid rgba(255,255,255,0.6)',
          transition:'transform 0.05s',
          pointerEvents:'none',
        }} />
      </div>

      {/* Right-side action buttons */}
      <div style={{
        position:'absolute', bottom:20, right:16,
        display:'grid', gridTemplateColumns:'1fr 1fr',
        gap:10, pointerEvents:'auto', touchAction:'none',
      }}>
        <div {...btn('↑ Jump','jump')} />
        <div {...btn('↓ Fly','flyDown')} />
        <div {...btn('⛏ Break','breakBlock',{ background:'rgba(180,50,50,0.55)' })} />
        <div {...btn('📦 Place','placeBlock',{ background:'rgba(50,120,180,0.55)' })} />
      </div>

      {/* Mode toggle button (top-right) */}
      <div
        data-btn="1"
        onTouchStart={(e) => { e.stopPropagation(); stateRef.current.toggleMode = true; }}
