     7→import { BlockType, isSolid, HOTBAR_CREATIVE, HOTBAR_SURVIVAL } from './blocks';
     8→
     9→const SPEED = 5;
    10→const CREATIVE_SPEED = 8;
    11→const FLY_SPEED = 12;
    12→const JUMP_FORCE = 7;
    13→const GRAVITY = 22;
    14→const PLAYER_H = 1.8;
    15→const PLAYER_W = 0.58;
    16→const EYE_H = 1.6;
    17→const MAX_REACH_CREATIVE = 6;
    18→const MAX_REACH_SURVIVAL = 4;
    19→const BREAK_TIME_MS = 900;
    20→
    21→interface PlayerProps {
    22→  mode: 'CREATIVE' | 'SURVIVAL';
    23→  setMode: (m: 'CREATIVE' | 'SURVIVAL') => void;
    24→  playerChunkRef: React.MutableRefObject<{ x: number; z: number }>;
