    30→  touchRef: React.MutableRefObject<{ dx: number; dz: number; jump: boolean; doBreak: boolean; doPlace: boolean }>;
    31→}
    32→
    33→function collidesAt(pos: THREE.Vector3): boolean {
    34→  const hw = PLAYER_W / 2;
    35→  const x0 = Math.floor(pos.x - hw), x1 = Math.floor(pos.x + hw - 0.001);
    36→  const y0 = Math.floor(pos.y),      y1 = Math.floor(pos.y + PLAYER_H - 0.001);
    37→  const z0 = Math.floor(pos.z - hw), z1 = Math.floor(pos.z + hw - 0.001);
    38→  for (let bx = x0; bx <= x1; bx++)
    39→    for (let by = y0; by <= y1; by++)
    40→      for (let bz = z0; bz <= z1; bz++)
    41→        if (isSolid(worldManager.getBlock(bx, by, bz))) return true;
    42→  return false;
    43→}
    44→
    45→function castRay(origin: THREE.Vector3, dir: THREE.Vector3, maxD: number) {
    46→  const d = dir.clone().normalize();
    47→  let bx = Math.floor(origin.x), by = Math.floor(origin.y), bz = Math.floor(origin.z);
    48→  const sx = d.x > 0 ? 1 : -1, sy = d.y > 0 ? 1 : -1, sz = d.z > 0 ? 1 : -1;
    49→  const dtx = d.x !== 0 ? Math.abs(1/d.x) : Infinity;
    50→  const dty = d.y !== 0 ? Math.abs(1/d.y) : Infinity;
    51→  const dtz = d.z !== 0 ? Math.abs(1/d.z) : Infinity;
    52→  let tmx = d.x !== 0 ? (sx>0 ? Math.ceil(origin.x)-origin.x : origin.x-Math.floor(origin.x)) / Math.abs(d.x) : Infinity;
    53→  let tmy = d.y !== 0 ? (sy>0 ? Math.ceil(origin.y)-origin.y : origin.y-Math.floor(origin.y)) / Math.abs(d.y) : Infinity;
    54→  let tmz = d.z !== 0 ? (sz>0 ? Math.ceil(origin.z)-origin.z : origin.z-Math.floor(origin.z)) / Math.abs(d.z) : Infinity;
    55→  if (tmx === 0) tmx = dtx;
    56→  if (tmy === 0) tmy = dty;
    57→  if (tmz === 0) tmz = dtz;
    58→  let pbx = bx, pby = by, pbz = bz;
    59→  let nx = 0, ny = 0, nz = 0;
    60→  let t = 0;
    61→  while (t < maxD) {
    62→    if (isSolid(worldManager.getBlock(bx, by, bz))) {
    63→      return { hit: true, hitPos: new THREE.Vector3(bx,by,bz), prevPos: new THREE.Vector3(pbx,pby,pbz), normal: new THREE.Vector3(nx,ny,nz) };
    64→    }
    65→    pbx = bx; pby = by; pbz = bz;
    66→    if (tmx < tmy && tmx < tmz) { t = tmx; bx += sx; tmx += dtx; nx = -sx; ny = 0; nz = 0; }
    67→    else if (tmy < tmz)          { t = tmy; by += sy; tmy += dty; nx = 0; ny = -sy; nz = 0; }
    68→    else                          { t = tmz; bz += sz; tmz += dtz; nx = 0; ny = 0; nz = -sz; }
    69→  }
    70→  return { hit: false, hitPos: null, prevPos: null, normal: null };
    71→}
