    73→export default function Player({ mode, setMode, playerChunkRef, onStateChange, touchRef }: PlayerProps) {
    74→  const { camera, gl } = useThree();
    75→  const [, getKeys] = useKeyboardControls<Controls>();
    76→
    77→  const pos   = useRef(new THREE.Vector3(8, 30, 8));
    78→  const vel   = useRef(new THREE.Vector3());
    79→  const yaw   = useRef(0);
    80→  const pitch = useRef(0);
    81→  const grounded  = useRef(false);
    82→  const flying    = useRef(mode === 'CREATIVE');
    83→  const modeRef   = useRef(mode);
    84→  const hotbar    = useRef<BlockType[]>([...HOTBAR_CREATIVE]);
    85→  const slot      = useRef(0);
    86→  const health    = useRef(20);
    87→  const hunger    = useRef(20);
    88→  const lmbDown   = useRef(false);
    89→  const rmbDown   = useRef(false);
    90→  const breakStart = useRef(0);
    91→  const breakPos  = useRef<THREE.Vector3 | null>(null);
    92→  const lastPlace = useRef(0);
    93→  const stateT    = useRef(0);
    94→  const spaceLastTap = useRef(0);
    95→  const prevMode  = useRef(mode);
    96→  const dir3      = useRef(new THREE.Vector3());
    97→  const eyePos    = useRef(new THREE.Vector3());
    98→  const tmpPos    = useRef(new THREE.Vector3());
    99→
   100→  // Init camera
   101→  useEffect(() => {
   102→    camera.rotation.order = 'YXZ';
   103→    const spawnY = worldManager.getTerrainHeight(8, 8) + 3;
   104→    pos.current.set(8, spawnY, 8);
   105→    console.log('[VoxelCraft] Player spawned at y=', spawnY);
   106→  }, [camera]);
   107→
   108→  // Pointer lock
   109→  useEffect(() => {
   110→    const el = gl.domElement;
   111→
   112→    const lock = () => {
   113→      if (document.pointerLockElement !== el) {
   114→        el.requestPointerLock();
   115→      }
   116→    };
   117→
   118→    el.addEventListener('click', lock);
   119→    el.addEventListener('touchstart', lock);
   120→
   121→    return () => {
   122→      el.removeEventListener('click', lock);
   123→      el.removeEventListener('touchstart', lock);
   124→    };
   125→  }, [gl.domElement]);
   126→
   127→  // Mouse look
   128→  useEffect(() => {
   129→    const el = gl.domElement;
   130→    const onMove = (e: MouseEvent) => {
   131→      if (document.pointerLockElement !== el) return;
   132→      yaw.current   -= e.movementX * 0.002;
   133→      pitch.current -= e.movementY * 0.002;
   134→      pitch.current  = Math.max(-1.5, Math.min(1.5, pitch.current));
   135→    };
   136→    document.addEventListener('mousemove', onMove);
   137→    return () => document.removeEventListener('mousemove', onMove);
   138→  }, [gl]);
   139→
   140→  // Mouse buttons
   141→  useEffect(() => {
   142→    const el = gl.domElement;
   143→    const dn = (e: MouseEvent) => {
   144→      if (document.pointerLockElement !== el) return;
   145→      if (e.button === 0) { lmbDown.current = true; breakStart.current = 0; breakPos.current = null; }
   146→      if (e.button === 2) rmbDown.current = true;
   147→    };
   148→    const up = (e: MouseEvent) => {
   149→      if (e.button === 0) { lmbDown.current = false; breakStart.current = 0; breakPos.current = null; }
   150→      if (e.button === 2) rmbDown.current = false;
   151→    };
   152→    const ctx = (e: Event) => e.preventDefault();
   153→    document.addEventListener('mousedown', dn);
   154→    document.addEventListener('mouseup', up);
   155→    document.addEventListener('contextmenu', ctx);
   156→    return () => {
   157→      document.removeEventListener('mousedown', dn);
   158→      document.removeEventListener('mouseup', up);
   159→      document.removeEventListener('contextmenu', ctx);
   160→    };
   161→  }, [gl]);
   162→
   163→  // Keyboard: numbers, scroll, double-space fly
   164→  useEffect(() => {
   165→    const dn = (e: KeyboardEvent) => {
   166→      const n = parseInt(e.code.replace('Digit',''));
   167→      if (n >= 1 && n <= 9) slot.current = n - 1;
   168→      if (e.code === 'Space' && modeRef.current === 'CREATIVE') {
   169→        const now = Date.now();
   170→        if (now - spaceLastTap.current < 350) flying.current = !flying.current;
   171→        spaceLastTap.current = now;
   172→      }
   173→    };
   174→    const wh = (e: WheelEvent) => {
   175→      slot.current = ((slot.current + (e.deltaY > 0 ? 1 : -1)) + 9) % 9;
   176→    };
   177→    window.addEventListener('keydown', dn);
   178→    window.addEventListener('wheel', wh);
   179→    return () => { window.removeEventListener('keydown', dn); window.removeEventListener('wheel', wh); };
   180→  }, []);
   181→
   182→  // Sync mode
   183→  useEffect(() => {
   184→    modeRef.current = mode;
   185→    if (mode !== prevMode.current) {
   186→      prevMode.current = mode;
   187→      hotbar.current = mode === 'CREATIVE' ? [...HOTBAR_CREATIVE] : [...HOTBAR_SURVIVAL];
   188→      if (mode !== 'CREATIVE') flying.current = false;
   189→    }
   190→  }, [mode]);
   191→
   192→  useFrame((_, delta) => {
   193→    const dt = Math.min(delta, 0.05);
   194→    const k = getKeys();
   195→    const t = touchRef.current;
   196→    const locked = document.pointerLockElement === gl.domElement;
   197→
   198→    // Movement
   199→    const curMode = modeRef.current;
   200→    const isFlying = flying.current && curMode === 'CREATIVE';
   201→    const spd = isFlying ? FLY_SPEED : (curMode === 'CREATIVE' ? CREATIVE_SPEED : SPEED);
   202→    const sinY = Math.sin(yaw.current), cosY = Math.cos(yaw.current);
   203→
   204→    // Keyboard + touch combined
   205→    const fwd = k.forward || false;
   206→    const bk  = k.back    || false;
   207→    const lft = k.left    || false;
   208→    const rgt = k.right   || false;
   209→    const jmp = k.jump    || t.jump;
   210→
   211→    let mx = 0, mz = 0;
   212→    if (fwd) { mx -= sinY; mz -= cosY; }
