   215→    if (rgt) { mx += cosY; mz -= sinY; }
   216→    // Touch joystick
   217→    if (t.dx !== 0 || t.dz !== 0) {
   218→      mx = -sinY * t.dz - cosY * t.dx;
   219→      mz = -cosY * t.dz + sinY * t.dx;
   220→    }
   221→    const ml = Math.sqrt(mx*mx + mz*mz);
   222→    if (ml > 0) { mx /= ml; mz /= ml; }
   223→
   224→    vel.current.x = mx * spd;
   225→    vel.current.z = mz * spd;
   226→
   227→    if (isFlying) {
