   235→    }
   236→
   237→    // AABB collision resolution
   238→    const p = pos.current, v = vel.current;
   239→
   240→    tmpPos.current.set(p.x + v.x * dt, p.y, p.z);
   241→    if (!collidesAt(tmpPos.current)) p.x = tmpPos.current.x;
   242→    else v.x = 0;
   243→
   244→    tmpPos.current.set(p.x, p.y + v.y * dt, p.z);
   245→    if (!collidesAt(tmpPos.current)) {
   246→      p.y = tmpPos.current.y;
   247→      if (!isFlying) grounded.current = false;
   248→    } else {
