   253→        }
   254→      }
   255→      v.y = 0;
   256→    }
   257→
   258→    tmpPos.current.set(p.x, p.y, p.z + v.z * dt);
   259→    if (!collidesAt(tmpPos.current)) p.z = tmpPos.current.z;
   260→    else v.z = 0;
   261→
   262→    // Void safety
   263→    if (p.y < -10) {
   264→      p.set(8, worldManager.getTerrainHeight(8, 8) + 3, 8);
   265→      v.set(0, 0, 0);
   266→      if (curMode === 'SURVIVAL') health.current = Math.max(0, health.current - 4);
   267→    }
   268→
   269→    // Camera
   270→    camera.rotation.y = yaw.current;
   271→    camera.rotation.x = pitch.current;
   272→    eyePos.current.set(p.x, p.y + EYE_H, p.z);
   273→    camera.position.copy(eyePos.current);
   274→
   275→    // Chunk tracking
   276→    playerChunkRef.current = { x: Math.floor(p.x / CHUNK_SIZE), z: Math.floor(p.z / CHUNK_SIZE) };
   277→
   278→    // Block interaction
   279→    if (locked || t.doBreak || t.doPlace) {
