   284→      const doBreak = lmbDown.current || t.doBreak;
   285→      const doPlace = rmbDown.current || t.doPlace;
   286→
   287→      if (ray.hit && ray.hitPos) {
   288→        if (doBreak) {
   289→          const now = Date.now();
   290→          const hp = ray.hitPos;
   291→          if (curMode === 'CREATIVE') {
   292→            if (now - breakStart.current > 200) {
   293→              worldManager.setBlock(hp.x, hp.y, hp.z, BlockType.AIR);
   294→              breakStart.current = now;
   295→            }
   296→          } else {
   297→            const samePos = breakPos.current && breakPos.current.equals(hp);
   298→            if (!samePos) { breakPos.current = hp.clone(); breakStart.current = now; }
   299→            if (now - breakStart.current >= BREAK_TIME_MS) {
   300→              worldManager.setBlock(hp.x, hp.y, hp.z, BlockType.AIR);
   301→              breakPos.current = null; breakStart.current = 0;
   302→            }
   303→          }
   304→        } else {
   305→          breakPos.current = null; breakStart.current = 0;
   306→        }
   307→
   308→        if (doPlace && ray.prevPos) {
   309→          const now = Date.now();
   310→          if (now - lastPlace.current > 250) {
   311→            const pp = ray.prevPos;
   312→            const blk = hotbar.current[slot.current];
   313→            if (blk !== BlockType.AIR) {
   314→              // Don't place inside player
   315→              const hw = PLAYER_W / 2;
   316→              const px0 = Math.floor(p.x - hw), px1 = Math.floor(p.x + hw - 0.001);
   317→              const py0 = Math.floor(p.y),       py1 = Math.floor(p.y + PLAYER_H - 0.001);
   318→              const pz0 = Math.floor(p.z - hw), pz1 = Math.floor(p.z + hw - 0.001);
   319→              const inside = pp.x >= px0 && pp.x <= px1 && pp.y >= py0 && pp.y <= py1 && pp.z >= pz0 && pp.z <= pz1;
   320→              if (!inside) {
   321→                worldManager.setBlock(pp.x, pp.y, pp.z, blk);
   322→                lastPlace.current = now;
   323→              }
   324→            }
   325→          }
   326→        }
   327→      } else {
   328→        breakPos.current = null; breakStart.current = 0;
   329→      }
   330→    }
   331→
   332→    // Hunger decay + HUD sync
   333→    stateT.current += dt;
   334→    if (stateT.current > 0.1) {
   335→      stateT.current = 0;
   336→      if (curMode === 'SURVIVAL') hunger.current = Math.max(0, hunger.current - 0.002);
