import { useRef, useEffect } from 'react';

export interface TouchState {
  dx: number; dz: number;
  jump: boolean; doBreak: boolean; doPlace: boolean;
  flyDown: boolean; toggleMode: boolean;
  lookDx: number; lookDy: number;
}

export function createTouchState(): TouchState {
  return { dx:0, dz:0, jump:false, doBreak:false, doPlace:false, flyDown:false, toggleMode:false, lookDx:0, lookDy:0 };
}

interface Props { stateRef: React.MutableRefObject<TouchState>; }

const RADIUS = 52;

export default function TouchControls({ stateRef }: Props) {
  const baseRef    = useRef<HTMLDivElement>(null);
  const thumbRef   = useRef<HTMLDivElement>(null);
  const joyTouchId = useRef<number | null>(null);
  const joyCenter  = useRef({ x: 0, y: 0 });
  const lookTouchId = useRef<number | null>(null);
  const lookPrev    = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const base = baseRef.current;
    if (!base) return;

    // ─── Joystick listeners (on the joystick element only) ───────────
    const joyStart = (e: TouchEvent) => {
      e.stopPropagation();
      if (joyTouchId.current !== null) return;
      const t = e.changedTouches[0];
      const r = base.getBoundingClientRect();
      joyTouchId.current = t.identifier;
      joyCenter.current  = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    };

    const joyMove = (e: TouchEvent) => {
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        if (t.identifier !== joyTouchId.current) continue;
        const rx = t.clientX - joyCenter.current.x;
        const ry = t.clientY - joyCenter.current.y;
        const len = Math.sqrt(rx*rx + ry*ry);
        const c = Math.min(len, RADIUS);
        const nx = len > 0 ? rx / len * c / RADIUS : 0;
        const ny = len > 0 ? ry / len * c / RADIUS : 0;
        stateRef.current.dx = nx;
        stateRef.current.dz = ny;          // positive ny = down = backward
        if (thumbRef.current) thumbRef.current.style.transform = `translate(${nx*RADIUS}px,${ny*RADIUS}px)`;
      }
    };

    const joyEnd = (e: TouchEvent) => {
      for (let i = 0; i < e.changedTouches.length; i++) {
        if (e.changedTouches[i].identifier === joyTouchId.current) {
          joyTouchId.current = null;
          stateRef.current.dx = 0; stateRef.current.dz = 0;
          if (thumbRef.current) thumbRef.current.style.transform = '';
        }
      }
    };

    base.addEventListener('touchstart', joyStart, { passive: true });
    base.addEventListener('touchmove',  joyMove,  { passive: true });
    base.addEventListener('touchend',   joyEnd,   { passive: true });
    base.addEventListener('touchcancel',joyEnd,   { passive: true });

    // ─── Global look-zone listener (right half of screen) ───────────
    const docStart = (e: TouchEvent) => {
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        if (t.clientX < window.innerWidth * 0.38) continue; // left side = joystick
        if (lookTouchId.current !== null) continue;
        // Ignore touches on button elements
        const el = document.elementFromPoint(t.clientX, t.clientY) as HTMLElement | null;
        if (el?.closest('[data-touch-btn]')) continue;
        lookTouchId.current = t.identifier;
        lookPrev.current = { x: t.clientX, y: t.clientY };
      }
    };

    const docMove = (e: TouchEvent) => {
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        if (t.identifier !== lookTouchId.current) continue;
        stateRef.current.lookDx += t.clientX - lookPrev.current.x;
        stateRef.current.lookDy += t.clientY - lookPrev.current.y;
        lookPrev.current = { x: t.clientX, y: t.clientY };
      }
    };

    const docEnd = (e: TouchEvent) => {
      for (let i = 0; i < e.changedTouches.length; i++) {
        if (e.changedTouches[i].identifier === lookTouchId.current) lookTouchId.current = null;
      }
    };

    document.addEventListener('touchstart', docStart, { passive: true });
    document.addEventListener('touchmove',  docMove,  { passive: true });
    document.addEventListener('touchend',   docEnd,   { passive: true });
    document.addEventListener('touchcancel',docEnd,   { passive: true });

    return () => {
      base.removeEventListener('touchstart', joyStart);
      base.removeEventListener('touchmove',  joyMove);
      base.removeEventListener('touchend',   joyEnd);
      base.removeEventListener('touchcancel',joyEnd);
      document.removeEventListener('touchstart', docStart);
      document.removeEventListener('touchmove',  docMove);
      document.removeEventListener('touchend',   docEnd);
      document.removeEventListener('touchcancel',docEnd);
    };
  }, [stateRef]);

  const makeBtn = (label: string, key: keyof TouchState, bg: string, momentary = true) => ({
    onTouchStart: (e: React.TouchEvent) => { e.stopPropagation(); (stateRef.current as any)[key] = true; },
    onTouchEnd:   (e: React.TouchEvent) => { e.stopPropagation(); if (momentary) (stateRef.current as any)[key] = false; },
    'data-touch-btn': '1',
    style: {
      width:64, height:50, borderRadius:10, border:`2px solid ${bg}`,
      background: bg + '66', color:'#fff', fontSize:11, fontWeight:700,
      display:'flex', alignItems:'center', justifyContent:'center',
      userSelect:'none' as const, touchAction:'none',
    },
  });

  return (
    <div style={{ position:'absolute', inset:0, pointerEvents:'none', zIndex:20 }}>

      {/* Joystick */}
      <div
        ref={baseRef}
        style={{
          position:'absolute', bottom:80, left:24,
          width:108, height:108, borderRadius:'50%',
          background:'rgba(255,255,255,0.10)', border:'2px solid rgba(255,255,255,0.28)',
          display:'flex', alignItems:'center', justifyContent:'center',
          pointerEvents:'auto', touchAction:'none',
        }}
      >
        <div ref={thumbRef} style={{
          width:46, height:46, borderRadius:'50%',
          background:'rgba(255,255,255,0.38)',
          pointerEvents:'none', transition:'none',
        }} />
      </div>

      {/* Action buttons (bottom-right) */}
      <div
        data-touch-btn="1"
        style={{
          position:'absolute', bottom:80, right:16,
          display:'grid', gridTemplateColumns:'repeat(2,1fr)', gap:8,
          pointerEvents:'auto',
        }}
      >
        <div {...makeBtn('↑ Jump',   'jump',    '#3399ff')} />
        <div {...makeBtn('↓ Fly Dn', 'flyDown', '#9966ff')} />
        <div {...makeBtn('⛏ Break', 'doBreak', '#ff4444')} />
        <div {...makeBtn('📦 Place', 'doPlace', '#44cc66')} />
      </div>

      {/* Mode toggle (top-right) */}
      <div
        data-touch-btn="1"
        onTouchStart={(e) => { e.stopPropagation(); stateRef.current.toggleMode = true; }}
        onTouchEnd={(e)   => { e.stopPropagation(); stateRef.current.toggleMode = false; }}
        style={{
          position:'absolute', top:14, right:14, pointerEvents:'auto', touchAction:'none',
          padding:'7px 16px', borderRadius:20,
          background:'rgba(80,40,120,0.75)', border:'2px solid rgba(180,130,255,0.6)',
          color:'#ddd', fontSize:11, fontWeight:700,
          userSelect:'none',
        }}
      >
        ⚙ MODE
      </div>
    </div>
  );
}

import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { useKeyboardControls } from '@react-three/drei';
import * as THREE from 'three';
import { Controls } from './Game';
import { worldManager, CHUNK_SIZE } from './worldGen';
import { BlockType, isSolid, HOTBAR_CREATIVE, HOTBAR_SURVIVAL } from './blocks';
import { raycastMobs, damageMob } from './mobSystem';
import type { TouchState } from './TouchControls';

const SPEED = 5;
const CREATIVE_SPEED = 8;
const FLY_SPEED = 12;
const JUMP_FORCE = 7;
const GRAVITY = 22;
const PLAYER_H = 1.8;
const PLAYER_W = 0.58;
const EYE_H = 1.6;
const MAX_REACH_CREATIVE = 6;
const MAX_REACH_SURVIVAL = 4;
const BREAK_TIME_MS = 900;

interface PlayerProps {
  mode: 'CREATIVE' | 'SURVIVAL';
  setMode: (m: 'CREATIVE' | 'SURVIVAL') => void;
  playerChunkRef: React.MutableRefObject<{ x: number; z: number }>;
  onStateChange: (s: {
    health: number; hunger: number;
    hotbar: BlockType[]; selectedSlot: number;
    pos: THREE.Vector3;
  }) => void;
  touchRef: React.MutableRefObject<TouchState>;
}

function collidesAt(pos: THREE.Vector3): boolean {
  const hw = PLAYER_W / 2;
  const x0 = Math.floor(pos.x - hw), x1 = Math.floor(pos.x + hw - 0.001);
  const y0 = Math.floor(pos.y),      y1 = Math.floor(pos.y + PLAYER_H - 0.001);
  const z0 = Math.floor(pos.z - hw), z1 = Math.floor(pos.z + hw - 0.001);
  for (let bx = x0; bx <= x1; bx++)
    for (let by = y0; by <= y1; by++)
      for (let bz = z0; bz <= z1; bz++)
        if (isSolid(worldManager.getBlock(bx, by, bz))) return true;
  return false;
}

function castRay(origin: THREE.Vector3, dir: THREE.Vector3, maxD: number) {
  const d = dir.clone().normalize();
  let bx = Math.floor(origin.x), by = Math.floor(origin.y), bz = Math.floor(origin.z);
  const sx = d.x > 0 ? 1 : -1, sy = d.y > 0 ? 1 : -1, sz = d.z > 0 ? 1 : -1;
  const dtx = d.x !== 0 ? Math.abs(1/d.x) : Infinity;
  const dty = d.y !== 0 ? Math.abs(1/d.y) : Infinity;
  const dtz = d.z !== 0 ? Math.abs(1/d.z) : Infinity;
  let tmx = d.x !== 0 ? (sx>0 ? Math.ceil(origin.x)-origin.x : origin.x-Math.floor(origin.x)) / Math.abs(d.x) : Infinity;
  let tmy = d.y !== 0 ? (sy>0 ? Math.ceil(origin.y)-origin.y : origin.y-Math.floor(origin.y)) / Math.abs(d.y) : Infinity;
  let tmz = d.z !== 0 ? (sz>0 ? Math.ceil(origin.z)-origin.z : origin.z-Math.floor(origin.z)) / Math.abs(d.z) : Infinity;
  if (tmx === 0) tmx = dtx; if (tmy === 0) tmy = dty; if (tmz === 0) tmz = dtz;
  let pbx = bx, pby = by, pbz = bz, nx = 0, ny = 0, nz = 0, t = 0;
  while (t < maxD) {
    if (isSolid(worldManager.getBlock(bx, by, bz)))
      return { hit:true, hitPos:new THREE.Vector3(bx,by,bz), prevPos:new THREE.Vector3(pbx,pby,pbz), normal:new THREE.Vector3(nx,ny,nz), dist:t };
    pbx=bx; pby=by; pbz=bz;
    if (tmx<tmy && tmx<tmz) { t=tmx; bx+=sx; tmx+=dtx; nx=-sx; ny=0; nz=0; }
    else if (tmy<tmz)        { t=tmy; by+=sy; tmy+=dty; nx=0; ny=-sy; nz=0; }
    else                      { t=tmz; bz+=sz; tmz+=dtz; nx=0; ny=0; nz=-sz; }
  }
  return { hit:false, hitPos:null, prevPos:null, normal:null, dist:maxD };
}

export default function Player({ mode, setMode, playerChunkRef, onStateChange, touchRef }: PlayerProps) {
  const { camera, gl } = useThree();
  const [, getKeys] = useKeyboardControls<Controls>();

  const pos         = useRef(new THREE.Vector3(8, 30, 8));
  const vel         = useRef(new THREE.Vector3());
  const yaw         = useRef(0);
  const pitch       = useRef(0);
  const grounded    = useRef(false);
  const flying      = useRef(mode === 'CREATIVE');
  const modeRef     = useRef(mode);
  const hotbar      = useRef<BlockType[]>([...HOTBAR_CREATIVE]);
  const slot        = useRef(0);
  const health      = useRef(20);
  const hunger      = useRef(20);
  const lmbDown     = useRef(false);
  const rmbDown     = useRef(false);
  const breakStart  = useRef(0);
  const breakPos    = useRef<THREE.Vector3 | null>(null);
  const lastPlace   = useRef(0);
  const stateT      = useRef(0);
  const spaceLastTap= useRef(0);
  const prevMode    = useRef(mode);
  const dir3        = useRef(new THREE.Vector3());
  const eyePos      = useRef(new THREE.Vector3());
  const tmpPos      = useRef(new THREE.Vector3());
  const lastHit     = useRef(0);
  const prevToggleMode = useRef(false);

  useEffect(() => {
    camera.rotation.order = 'YXZ';
    const spawnY = worldManager.getTerrainHeight(8, 8) + 3;
    pos.current.set(8, spawnY, 8);
  }, [camera]);

  // Pointer lock
  useEffect(() => {
    const el = gl.domElement;
    const lock = () => { if (document.pointerLockElement !== el) el.requestPointerLock(); };
    el.addEventListener('click', lock);
    return () => el.removeEventListener('click', lock);
  }, [gl.domElement]);

  // Mouse look
  useEffect(() => {
    const el = gl.domElement;
    const onMove = (e: MouseEvent) => {
      if (document.pointerLockElement !== el) return;
      yaw.current   -= e.movementX * 0.002;
      pitch.current -= e.movementY * 0.002;
      pitch.current  = Math.max(-1.5, Math.min(1.5, pitch.current));
    };
    document.addEventListener('mousemove', onMove);
    return () => document.removeEventListener('mousemove', onMove);
  }, [gl]);

  // Mouse buttons
  useEffect(() => {
    const el = gl.domElement;
    const dn = (e: MouseEvent) => {
      if (document.pointerLockElement !== el) return;
      if (e.button === 0) { lmbDown.current = true; breakStart.current = 0; breakPos.current = null; }
      if (e.button === 2) rmbDown.current = true;
    };
    const up = (e: MouseEvent) => {
      if (e.button === 0) { lmbDown.current = false; breakStart.current = 0; breakPos.current = null; }
      if (e.button === 2) rmbDown.current = false;
    };
    const ctx = (e: Event) => e.preventDefault();
    document.addEventListener('mousedown', dn);
    document.addEventListener('mouseup', up);
    document.addEventListener('contextmenu', ctx);
    return () => {
      document.removeEventListener('mousedown', dn);
      document.removeEventListener('mouseup', up);
      document.removeEventListener('contextmenu', ctx);
    };
  }, [gl]);

  // Keyboard: slot, scroll, double-space fly
  useEffect(() => {
    const dn = (e: KeyboardEvent) => {
      const n = parseInt(e.code.replace('Digit',''));
      if (n >= 1 && n <= 9) slot.current = n - 1;
      if (e.code === 'Space' && modeRef.current === 'CREATIVE') {
        const now = Date.now();
        if (now - spaceLastTap.current < 350) flying.current = !flying.current;
        spaceLastTap.current = now;
      }
    };
    const wh = (e: WheelEvent) => { slot.current = ((slot.current + (e.deltaY > 0 ? 1 : -1)) + 9) % 9; };
    window.addEventListener('keydown', dn);
    window.addEventListener('wheel', wh);
    return () => { window.removeEventListener('keydown', dn); window.removeEventListener('wheel', wh); };
  }, []);

  // Sync mode
  useEffect(() => {
    modeRef.current = mode;
    if (mode !== prevMode.current) {
      prevMode.current = mode;
      hotbar.current = mode === 'CREATIVE' ? [...HOTBAR_CREATIVE] : [...HOTBAR_SURVIVAL];
      if (mode !== 'CREATIVE') flying.current = false;
    }
  }, [mode]);

  useFrame((_, delta) => {
    const dt = Math.min(delta, 0.05);
    const k  = getKeys();
    const t  = touchRef.current;
    const locked = document.pointerLockElement === gl.domElement;
    const curMode = modeRef.current;

    // ── Touch look ───────────────────────────────────────────────────
    if (t.lookDx !== 0 || t.lookDy !== 0) {
      yaw.current   -= t.lookDx * 0.004;
      pitch.current -= t.lookDy * 0.004;
      pitch.current  = Math.max(-1.5, Math.min(1.5, pitch.current));
      t.lookDx = 0; t.lookDy = 0;
    }

    // ── Touch mode toggle (edge-triggered) ───────────────────────────
    if (t.toggleMode && !prevToggleMode.current) {
      const next = curMode === 'CREATIVE' ? 'SURVIVAL' : 'CREATIVE';
      setMode(next);
    }
    prevToggleMode.current = t.toggleMode;

    // ── Movement ─────────────────────────────────────────────────────
    const isFlying = flying.current && curMode === 'CREATIVE';
    const spd = isFlying ? FLY_SPEED : (curMode === 'CREATIVE' ? CREATIVE_SPEED : SPEED);
    const sinY = Math.sin(yaw.current), cosY = Math.cos(yaw.current);

    const fwd = k.forward || false, bk = k.back || false;
    const lft = k.left    || false, rgt = k.right || false;
    const jmp = k.jump    || t.jump;

    let mx = 0, mz = 0;
    if (fwd) { mx -= sinY; mz -= cosY; }
    if (bk)  { mx += sinY; mz += cosY; }
    if (lft) { mx -= cosY; mz += sinY; }
    if (rgt) { mx += cosY; mz -= sinY; }

    // ── Fixed joystick: forward = dz<0, strafe-right = dx>0 ──────────
    if (t.dx !== 0 || t.dz !== 0) {
      mx = sinY * t.dz + cosY * t.dx;
      mz = cosY * t.dz - sinY * t.dx;
    }
    const ml = Math.sqrt(mx*mx + mz*mz);
    if (ml > 0) { mx /= ml; mz /= ml; }

    vel.current.x = mx * spd;
    vel.current.z = mz * spd;

    if (isFlying) {
      vel.current.y = 0;
      if (jmp)                         vel.current.y =  FLY_SPEED;
      if (k.sneak || t.flyDown)        vel.current.y = -FLY_SPEED;
    } else {
      if (jmp && grounded.current) { vel.current.y = JUMP_FORCE; grounded.current = false; }
      vel.current.y -= GRAVITY * dt;
      vel.current.y  = Math.max(vel.current.y, -50);
    }

    // ── AABB collision ────────────────────────────────────────────────
    const p = pos.current, v = vel.current;

    tmpPos.current.set(p.x + v.x * dt, p.y, p.z);
    if (!collidesAt(tmpPos.current)) p.x = tmpPos.current.x; else v.x = 0;

    tmpPos.current.set(p.x, p.y + v.y * dt, p.z);
    if (!collidesAt(tmpPos.current)) {
      p.y = tmpPos.current.y;
      if (!isFlying) grounded.current = false;
    } else {
      if (v.y < 0 && !isFlying) {
        grounded.current = true;
        if (curMode === 'SURVIVAL' && v.y < -12) health.current = Math.max(0, health.current - Math.floor((-v.y - 12) * 0.6));
      }
      v.y = 0;
    }

    tmpPos.current.set(p.x, p.y, p.z + v.z * dt);
    if (!collidesAt(tmpPos.current)) p.z = tmpPos.current.z; else v.z = 0;

    if (p.y < -10) {
      p.set(8, worldManager.getTerrainHeight(8, 8) + 3, 8);
      v.set(0, 0, 0);
      if (curMode === 'SURVIVAL') health.current = Math.max(0, health.current - 4);
    }

    // ── Camera ────────────────────────────────────────────────────────
    camera.rotation.y = yaw.current;
    camera.rotation.x = pitch.current;
    eyePos.current.set(p.x, p.y + EYE_H, p.z);
    camera.position.copy(eyePos.current);
    playerChunkRef.current = { x: Math.floor(p.x / CHUNK_SIZE), z: Math.floor(p.z / CHUNK_SIZE) };

    // ── Block + mob interaction ───────────────────────────────────────
    const doBreak = lmbDown.current || t.doBreak;
    const doPlace = rmbDown.current || t.doPlace;

    if (locked || doBreak || doPlace) {
      camera.getWorldDirection(dir3.current);
      const reach = curMode === 'CREATIVE' ? MAX_REACH_CREATIVE : MAX_REACH_SURVIVAL;
      const ray   = castRay(eyePos.current, dir3.current, reach);

      // Check mob hit BEFORE block hit
      const mobHit = doBreak
        ? raycastMobs(eyePos.current.x, eyePos.current.y, eyePos.current.z, dir3.current.x, dir3.current.y, dir3.current.z, reach)
        : null;

      if (mobHit && (!ray.hit || mobHit.dist < ray.dist)) {
        // Hit mob
        if (doBreak) {
          const now = Date.now();
          if (now - lastHit.current > 400) {
            damageMob(mobHit.id, curMode === 'CREATIVE' ? 10 : 5);
            lastHit.current = now;
          }
        }
      } else if (ray.hit && ray.hitPos) {
        if (doBreak) {
          const now = Date.now();
          const hp  = ray.hitPos;
          if (curMode === 'CREATIVE') {
            if (now - breakStart.current > 200) { worldManager.setBlock(hp.x, hp.y, hp.z, BlockType.AIR); breakStart.current = now; }
          } else {
            const samePos = breakPos.current?.equals(hp);
            if (!samePos) { breakPos.current = hp.clone(); breakStart.current = now; }
            if (now - breakStart.current >= BREAK_TIME_MS) { worldManager.setBlock(hp.x, hp.y, hp.z, BlockType.AIR); breakPos.current = null; breakStart.current = 0; }
          }
        } else { breakPos.current = null; breakStart.current = 0; }

        if (doPlace && ray.prevPos) {
          const now = Date.now();
          if (now - lastPlace.current > 250) {
            const pp  = ray.prevPos;
            const blk = hotbar.current[slot.current];
            if (blk !== BlockType.AIR) {
              const hw  = PLAYER_W / 2;
              const inside = pp.x >= Math.floor(p.x-hw) && pp.x <= Math.floor(p.x+hw-0.001)
                          && pp.y >= Math.floor(p.y)      && pp.y <= Math.floor(p.y+PLAYER_H-0.001)
                          && pp.z >= Math.floor(p.z-hw)   && pp.z <= Math.floor(p.z+hw-0.001);
              if (!inside) { worldManager.setBlock(pp.x, pp.y, pp.z, blk); lastPlace.current = now; }
            }
          }
        }
      } else { breakPos.current = null; breakStart.current = 0; }
    }

    // ── HUD sync ──────────────────────────────────────────────────────
    stateT.current += dt;
    if (stateT.current > 0.1) {
      stateT.current = 0;
      if (curMode === 'SURVIVAL') hunger.current = Math.max(0, hunger.current - 0.002);
      onStateChange({ health: health.current, hunger: hunger.current, hotbar: hotbar.current, selectedSlot: slot.current, pos: p.clone() });
    }
  });

  return null;
}

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { worldManager } from './worldGen';
import { isSolid } from './blocks';
import { getMobs, spawnMob, cleanDeadMobs, MOB_SPECS, MobState } from './mobSystem';

const SPAWN_DIST  = 24;
const DESPAWN_DIST= 48;
const GRAVITY     = 18;
const MAX_SPAWN   = 30;
const SPAWN_INTERVAL = 8; // seconds

function pseudoRand(n: number) {
  const s = Math.sin(n * 9301 + 49297) * 233280;
  return s - Math.floor(s);
}

// Mob materials (created once)
const matCache: Record<string, THREE.MeshLambertMaterial> = {};
function getMat(hex: number, flash = false): THREE.MeshLambertMaterial {
  const key = `${hex}${flash}`;
  if (!matCache[key]) {
    matCache[key] = new THREE.MeshLambertMaterial({ color: flash ? 0xff2020 : hex });
  }
  return matCache[key];
}

function MobMesh({ mob }: { mob: MobState }) {
  const groupRef = useRef<THREE.Group>(null);
  const headRef  = useRef<THREE.Mesh>(null);
  const spec     = MOB_SPECS[mob.type];

  const isFlashing  = mob.hitFlash > 0;
  const bodyColor   = isFlashing ? 0xff2020 : spec.color;
  const headColor   = isFlashing ? 0xff2020 : spec.headColor;

  const bodyH   = mob.type === 'spider' ? 0.5 : mob.type === 'slime' ? 0.8 : 1.1;
  const bodyW   = spec.hw * 2;
  const headSz  = mob.type === 'spider' ? 0.35 : mob.type === 'slime' ? 0.6 : 0.55;

  return (
    <group
      ref={groupRef}
      position={[mob.pos[0], mob.pos[1], mob.pos[2]]}
      rotation={[0, mob.yaw, 0]}
      scale={mob.state === 'dead' ? [1 - (1 - mob.deathTimer / 1.2), 1, 1 - (1 - mob.deathTimer / 1.2)] : [1,1,1]}
    >
      {/* Body */}
      <mesh position={[0, bodyH / 2, 0]}>
        <boxGeometry args={[bodyW, bodyH, bodyW * 0.8]} />
        <meshLambertMaterial color={bodyColor} />
      </mesh>
      {/* Head */}
      <mesh ref={headRef} position={[0, bodyH + headSz * 0.5 + 0.02, 0]}>
        <boxGeometry args={[headSz, headSz, headSz]} />
        <meshLambertMaterial color={headColor} />
      </mesh>
      {/* Eyes */}
      <mesh position={[headSz * 0.28, bodyH + headSz * 0.5 + 0.08, -headSz * 0.51]}>
        <boxGeometry args={[0.1, 0.08, 0.02]} />
        <meshLambertMaterial color={0xff2020} />
      </mesh>
      <mesh position={[-headSz * 0.28, bodyH + headSz * 0.5 + 0.08, -headSz * 0.51]}>
        <boxGeometry args={[0.1, 0.08, 0.02]} />
        <meshLambertMaterial color={0xff2020} />
      </mesh>
    </group>
  );
}

interface Props {
  playerPos: THREE.Vector3;
  onPlayerDamage: (amount: number) => void;
}

export default function Mobs({ playerPos, onPlayerDamage }: Props) {
  const spawnTimer = useRef(2); // first spawn in 2s
  const frameCount = useRef(0);

  useFrame((_, delta) => {
    const dt = Math.min(delta, 0.05);
    frameCount.current++;
    const mobs = getMobs();

    // ─── Spawn ─────────────────────────────────────────────────────
    spawnTimer.current -= dt;
    if (spawnTimer.current <= 0 && mobs.length < MAX_SPAWN) {
      spawnTimer.current = SPAWN_INTERVAL;
      const angle = pseudoRand(Date.now() * 0.001) * Math.PI * 2;
      const dist  = SPAWN_DIST * 0.7 + pseudoRand(Date.now() * 0.003) * SPAWN_DIST * 0.3;
      const sx    = playerPos.x + Math.cos(angle) * dist;
      const sz    = playerPos.z + Math.sin(angle) * dist;
      const sy    = worldManager.getTerrainHeight(Math.floor(sx), Math.floor(sz)) + 1;
      const types = ['zombie','zombie','zombie','skeleton','spider','creeper','slime'] as const;
      const tIdx  = Math.floor(pseudoRand(Date.now() * 0.007) * types.length);
      spawnMob(types[tIdx], sx, sy, sz);
    }

    // ─── Update each mob ───────────────────────────────────────────
    for (const mob of mobs) {
      const spec = MOB_SPECS[mob.type];

      // Timers
      if (mob.hitFlash > 0)       mob.hitFlash -= dt;
      if (mob.attackCooldown > 0) mob.attackCooldown -= dt;
      if (mob.patrolTimer > 0)    mob.patrolTimer -= dt;

      if (mob.state === 'dead') {
        mob.deathTimer -= dt;
        continue;
      }

      const dx = playerPos.x - mob.pos[0];
      const dz = playerPos.z - mob.pos[2];
      const dist2D = Math.sqrt(dx*dx + dz*dz);

      // Despawn far mobs
      if (dist2D > DESPAWN_DIST) { mob.state = 'dead'; mob.deathTimer = 0; continue; }

      // State transitions
      if (dist2D < spec.aggroRange) mob.state = 'aggro';
      else if (mob.state === 'aggro') mob.state = 'patrol';

      let vx = 0, vz = 0;

      if (mob.state === 'aggro' || mob.state === 'attack') {
        mob.yaw = Math.atan2(dx, dz);
        const speed = spec.speed * (mob.type === 'creeper' ? (dist2D < 4 ? 0.5 : 1) : 1);
        vx = (dx / dist2D) * speed * 60;
        vz = (dz / dist2D) * speed * 60;

        // Attack
        if (dist2D < spec.attackRange && mob.attackCooldown <= 0) {
          onPlayerDamage(spec.attackDamage);
          mob.attackCooldown = mob.type === 'creeper' ? 2.5 : mob.type === 'skeleton' ? 1.5 : 1.0;
        }
      } else if (mob.state === 'patrol' || mob.state === 'idle') {
        if (mob.patrolTimer <= 0) {
          const a = pseudoRand(Date.now() * 0.001 + mob.id) * Math.PI * 2;
          mob.patrolDir = [Math.cos(a) * 0.4, Math.sin(a) * 0.4];
          mob.patrolTimer = 2 + pseudoRand(mob.id + Date.now() * 0.0001) * 3;
          mob.state = 'patrol';
        }
        vx = mob.patrolDir[0] * 60;
        vz = mob.patrolDir[1] * 60;
        mob.yaw = Math.atan2(mob.patrolDir[0], mob.patrolDir[1]);
      }

      // Apply velocity with gravity
      mob.vel[0] = vx;
      mob.vel[2] = vz;
      mob.vel[1] -= GRAVITY * dt;
      mob.vel[1]  = Math.max(mob.vel[1], -30);

      // Move X
      const nx = mob.pos[0] + mob.vel[0] * dt;
      const nx2 = Math.floor(nx), mz2 = Math.floor(mob.pos[2]);
      const floorY = Math.floor(mob.pos[1]);
      if (!isSolid(worldManager.getBlock(nx2, floorY, mz2)) &&
          !isSolid(worldManager.getBlock(nx2, floorY + 1, mz2))) {
        mob.pos[0] = nx;
      } else {
        mob.vel[0] = 0;
        // Try to step up
        if (!isSolid(worldManager.getBlock(nx2, floorY + 2, mz2))) {
          mob.pos[1] += 0.15;
          mob.pos[0] = nx;
        }
      }

      // Move Z
      const nz = mob.pos[2] + mob.vel[2] * dt;
      const mx2 = Math.floor(mob.pos[0]), nz2 = Math.floor(nz);
      if (!isSolid(worldManager.getBlock(mx2, floorY, nz2)) &&
          !isSolid(worldManager.getBlock(mx2, floorY + 1, nz2))) {
        mob.pos[2] = nz;
      } else {
        mob.vel[2] = 0;
      }

      // Move Y (gravity)
      const newY = mob.pos[1] + mob.vel[1] * dt;
      const footY = Math.floor(newY);
      const headY = Math.floor(newY + spec.h);
      const mx3 = Math.floor(mob.pos[0]), mz3 = Math.floor(mob.pos[2]);
      if (mob.vel[1] < 0) {
        if (isSolid(worldManager.getBlock(mx3, footY, mz3))) {
          // Land on ground
          mob.pos[1] = footY + 1;
          mob.vel[1] = mob.type === 'slime' ? 4 : 0; // slime bounces
        } else {
          mob.pos[1] = newY;
        }
      } else {
        if (isSolid(worldManager.getBlock(mx3, headY, mz3))) mob.vel[1] = 0;
        else mob.pos[1] = newY;
      }
    }

    // Clean up dead mobs with expired timers
    if (frameCount.current % 60 === 0) cleanDeadMobs();
  });

  const mobs = getMobs();
  return (
    <>
      {mobs.map(mob => <MobMesh key={mob.id} mob={mob} />)}
    </>
  );
}

