function colorStr(t: BlockType): string {
  const c = BLOCK_COLORS[t];
  if (!c) return '#888';
  return `rgb(${Math.round(c[0]*255)},${Math.round(c[1]*255)},${Math.round(c[2]*255)})`;
}

interface Props {
  hotbar: BlockType[];
  onCraft: (result: BlockType, count: number, consume: { type: BlockType; count: number }[]) => void;
  onClose: () => void;
}

type Category = 'all' | 'building' | 'tools' | 'food' | 'misc';

export default function Crafting({ hotbar, onCraft, onClose }: Props) {
  const [category, setCategory] = useState<Category>('all');
  const [crafted,  setCrafted]  = useState<string | null>(null);

  // Count items in hotbar
  const inventory = useMemo(() => {
    const map: Record<number, number> = {};
    hotbar.forEach(t => { if (t !== BlockType.AIR) map[t] = (map[t] || 0) + 1; });
    return map;
  }, [hotbar]);

  const canCraft = (r: Recipe) =>
    r.ingredients.every(ing => (inventory[ing.type] || 0) >= ing.count);

  const filtered = RECIPES.filter(r => category === 'all' || r.category === category);
  const available = filtered.filter(r => canCraft(r));
  const unavailable = filtered.filter(r => !canCraft(r));
  const sorted = [...available, ...unavailable];

  function doCraft(r: Recipe) {
    if (!canCraft(r)) return;
    onCraft(r.result.type, r.result.count, r.ingredients);
    setCrafted(r.id);
    setTimeout(() => setCrafted(null), 800);
  }

  const cats: Category[] = ['all','building','tools','misc'];

  return (
    <div style={{
      position:'fixed', inset:0, zIndex:50,
      background:'rgba(0,0,0,0.78)',
      display:'flex', alignItems:'center', justifyContent:'center',
    }} onClick={onClose}>
      <div
        onClick={e => e.stopPropagation()}
        style={{
          background:'#1a1a2e', border:'2px solid #5cb85c',
          borderRadius:12, padding:20, width:420, maxWidth:'96vw', maxHeight:'88vh',
          overflow:'hidden', display:'flex', flexDirection:'column', gap:12,
          color:'#fff', fontFamily:'"Courier New",monospace',
        }}
      >
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div style={{ fontSize:20, fontWeight:700, color:'#5cb85c', letterSpacing:2 }}>⚒ CRAFTING</div>
          <div onClick={onClose} style={{ cursor:'pointer', fontSize:20, color:'#aaa', padding:'0 4px' }}>✕</div>
        </div>

        {/* Category tabs */}
        <div style={{ display:'flex', gap:6 }}>
          {cats.map(c => (
            <div key={c} onClick={() => setCategory(c)} style={{
              padding:'4px 10px', borderRadius:6, fontSize:11, cursor:'pointer',
              background: category === c ? '#5cb85c' : '#333',
              color: category === c ? '#000' : '#ccc',
              fontWeight:700, textTransform:'uppercase',
            }}>
              {c}
            </div>
          ))}
        </div>

        {/* Inventory summary */}
        <div style={{ fontSize:10, color:'#888', borderBottom:'1px solid #333', paddingBottom:6 }}>
          Inventory: {Object.entries(inventory).map(([k, v]) => `${BLOCK_NAMES[+k]??'?'} ×${v}`).join(', ') || 'empty'}
        </div>

        {/* Recipe list */}
        <div style={{ overflowY:'auto', display:'flex', flexDirection:'column', gap:6 }}>
          {sorted.map(r => {
            const can = canCraft(r);
            const justCrafted = crafted === r.id;
            return (
              <div
                key={r.id}
                onClick={() => doCraft(r)}
                style={{
                  display:'flex', alignItems:'center', gap:10,
                  padding:'8px 10px', borderRadius:8,
                  background: justCrafted ? '#1e5e1e' : can ? '#1a2e1a' : '#1a1a2a',
                  border: `1px solid ${justCrafted ? '#5cb85c' : can ? '#3d6b3d' : '#333'}`,
                  cursor: can ? 'pointer' : 'default',
                  opacity: can ? 1 : 0.55,
                  transition:'all 0.15s',
                }}
              >
                {/* Result swatch */}
                <div style={{
                  width:28, height:28, borderRadius:4, flexShrink:0,
                  background:colorStr(r.result.type),
                  border:'1px solid rgba(255,255,255,0.2)',
                  display:'flex', alignItems:'center', justifyContent:'center',
                  fontSize:11, color:'rgba(255,255,255,0.7)',
                }}>
                  {r.result.count > 1 ? r.result.count : ''}
                </div>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:12, fontWeight:700, color: can ? '#c8f0c8' : '#888' }}>{r.name}</div>
                  <div style={{ fontSize:10, color:'#666', marginTop:1 }}>
                    {r.ingredients.map(ing =>
                      `${BLOCK_NAMES[ing.type] ?? '?'} ×${ing.count}`
                    ).join(' + ')}
                  </div>
                </div>
                {can && (
                  <div style={{
                    fontSize:11, padding:'3px 8px', borderRadius:4,
                    background: justCrafted ? '#5cb85c' : '#3d6b3d',
                    color:'#fff', fontWeight:700,
                  }}>
                    {justCrafted ? '✓' : 'CRAFT'}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect, useCallback } from 'react';
import { Canvas } from '@react-three/fiber';
import { KeyboardControls } from '@react-three/drei';
import * as THREE from 'three';
import { BlockType, HOTBAR_CREATIVE } from './blocks';
import World from './World';
import Player from './Player';
import Animals from './Animals';
import Mobs from './Mobs';
import HUD from './HUD';
import TouchControls, { TouchState, createTouchState } from './TouchControls';
import Crafting from './Crafting';

export enum Controls {
  forward = 'forward',
  back    = 'back',
  left    = 'left',
  right   = 'right',
  jump    = 'jump',
  sneak   = 'sneak',
}

const KEY_MAP = [
  { name: Controls.forward, keys: ['ArrowUp',    'KeyW'] },
  { name: Controls.back,    keys: ['ArrowDown',  'KeyS'] },
  { name: Controls.left,    keys: ['ArrowLeft',  'KeyA'] },
  { name: Controls.right,   keys: ['ArrowRight', 'KeyD'] },
  { name: Controls.jump,    keys: ['Space'] },
  { name: Controls.sneak,   keys: ['ShiftLeft',  'ShiftRight'] },
];

interface UIState {
  health: number; hunger: number;
  hotbar: BlockType[]; selectedSlot: number;
  pos: { x: number; y: number; z: number };
  mode: 'CREATIVE' | 'SURVIVAL';
}

export default function Game() {
  const [started, setStarted]       = useState(false);
  const [craftingOpen, setCraftingOpen] = useState(false);
  const [uiState, setUiState]       = useState<UIState>({
    health: 20, hunger: 20,
    hotbar: [...HOTBAR_CREATIVE], selectedSlot: 0,
    pos: { x: 0, y: 0, z: 0 },
    mode: 'CREATIVE',
  });

  const playerChunkRef = useRef({ x: 0, z: 0 });
  const touchRef       = useRef<TouchState>(createTouchState());
  const playerPos      = useRef(new THREE.Vector3(8, 30, 8));

  // Tab → mode toggle (keyboard)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code === 'Tab')  { e.preventDefault(); setUiState(prev => ({ ...prev, mode: prev.mode === 'CREATIVE' ? 'SURVIVAL' : 'CREATIVE' })); }
      if (e.code === 'KeyE') { e.preventDefault(); if (started) setCraftingOpen(o => !o); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [started]);

  const handleStateChange = useCallback((s: {
    health: number; hunger: number;
    hotbar: BlockType[]; selectedSlot: number;
    pos: THREE.Vector3;
  }) => {
    playerPos.current.copy(s.pos);
    setUiState(prev => ({
      ...prev,
      health: s.health, hunger: s.hunger,
      hotbar: s.hotbar, selectedSlot: s.selectedSlot,
      pos: { x: s.pos.x, y: s.pos.y, z: s.pos.z },
    }));
  }, []);

  const handleMobDamage = useCallback((amount: number) => {
    setUiState(prev => {
      if (prev.mode !== 'SURVIVAL') return prev;
      return { ...prev, health: Math.max(0, prev.health - amount) };
    });
  }, []);

  const handleSetMode = useCallback((m: 'CREATIVE' | 'SURVIVAL') => {
    setUiState(prev => ({ ...prev, mode: m }));
  }, []);

  const handleCraft = useCallback((result: BlockType, count: number, consume: { type: BlockType; count: number }[]) => {
    setUiState(prev => {
      const hotbar = [...prev.hotbar];
      // Consume ingredients from hotbar
      consume.forEach(ing => {
        let need = ing.count;
        for (let i = 0; i < hotbar.length && need > 0; i++) {
          if (hotbar[i] === ing.type) { hotbar[i] = BlockType.AIR; need--; }
        }
      });
      // Add result to first empty slot
      let placed = false;
      for (let i = 0; i < hotbar.length; i++) {
        if (hotbar[i] === BlockType.AIR) { hotbar[i] = result; placed = true; break; }
      }
      // If hotbar full, replace selected slot
      if (!placed) hotbar[prev.selectedSlot] = result;
      return { ...prev, hotbar };
    });
  }, []);

  return (
    <div style={{ width:'100vw', height:'100vh', overflow:'hidden', background:'#000', position:'relative' }}>

      {/* Start screen */}
      {!started && (
        <div onClick={() => setStarted(true)} style={{
          position:'absolute', inset:0, zIndex:100,
          background:'linear-gradient(180deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
          display:'flex', alignItems:'center', justifyContent:'center',
          flexDirection:'column', color:'#fff', cursor:'pointer',
          fontFamily:'"Courier New", monospace',
        }}>
          <div style={{ fontSize:52, fontWeight:'bold', color:'#5cb85c', textShadow:'0 0 20px rgba(92,184,92,0.6)', letterSpacing:4, marginBottom:8 }}>
            VoxelCraft
          </div>
          <div style={{ fontSize:13, color:'#aaa', marginBottom:40, letterSpacing:1 }}>A 3D Voxel World — 226 Blocks · 10 Biomes · Mobs · Crafting</div>
          <div style={{ background:'rgba(92,184,92,0.2)', border:'2px solid #5cb85c', borderRadius:8, padding:'12px 32px', fontSize:18, color:'#5cb85c', letterSpacing:2 }}>
            ▶  CLICK TO PLAY
          </div>
          <div style={{ marginTop:40, fontSize:11, color:'rgba(255,255,255,0.4)', lineHeight:2, textAlign:'center' }}>
            WASD — Move &nbsp;|&nbsp; SPACE — Jump &nbsp;|&nbsp; SHIFT — Fly Down<br/>
            LMB — Break / Hit Mob &nbsp;|&nbsp; RMB — Place Block &nbsp;|&nbsp; Scroll — Hotbar<br/>
            E — Crafting &nbsp;|&nbsp; Tab — Toggle Creative/Survival &nbsp;|&nbsp; Double-Space — Fly
          </div>
        </div>
      )}

      {/* HUD */}
      {started && (
        <HUD
          mode={uiState.mode}
          health={uiState.health}
          hunger={uiState.hunger}
          hotbar={uiState.hotbar}
          selectedSlot={uiState.selectedSlot}
          pos={uiState.pos}
        />
      )}

      {/* Crafting button (mobile) */}
      {started && (
        <div
          onClick={() => setCraftingOpen(o => !o)}
          style={{
            position:'absolute', top:14, left:'50%', transform:'translateX(-50%)',
            zIndex:30, padding:'6px 14px', borderRadius:16,
            background:'rgba(50,50,80,0.8)', border:'1px solid rgba(100,100,180,0.6)',
            color:'#aac', fontSize:11, fontWeight:700, cursor:'pointer',
            userSelect:'none', pointerEvents:'auto',
          }}
        >
          ⚒ E — Craft
        </div>
      )}

      {/* Crafting overlay */}
      {craftingOpen && (
        <Crafting
          hotbar={uiState.hotbar}
          onCraft={handleCraft}
          onClose={() => setCraftingOpen(false)}
        />
      )}

      {/* Touch controls */}
      {started && <TouchControls stateRef={touchRef} />}

      {/* 3D Canvas */}
      <KeyboardControls map={KEY_MAP}>
        <Canvas
          camera={{ fov: 75, near: 0.05, far: 220 }}
          gl={{ antialias: false }}
          style={{ width:'100%', height:'100%' }}
        >
          <color attach="background" args={['#87CEEB']} />
          <fog attach="fog" args={['#aadcf0', 50, 110]} />
          <ambientLight intensity={0.45} />
          <directionalLight position={[50, 100, 30]} intensity={1.2} />

          <World playerChunkRef={playerChunkRef} />
          <Animals />

          {started && (
            <>
              <Mobs playerPos={playerPos.current} onPlayerDamage={handleMobDamage} />
              <Player
                mode={uiState.mode}
                setMode={handleSetMode}
                playerChunkRef={playerChunkRef}
                onStateChange={handleStateChange}
                touchRef={touchRef}
              />
            </>
          )}
        </Canvas>
      </KeyboardControls>
    </div>
  );
}

