     4→import { STRUCTURE_GENERATORS, StructureKey, BP } from './structures';
     5→
     6→export const CHUNK_SIZE = 16;
     7→export const WORLD_HEIGHT = 64;
     8→export const SEA_LEVEL = 6;
     9→
    10→export type ChunkData = Uint8Array;
    11→
    12→export function getChunkKey(cx: number, cz: number): string { return `${cx},${cz}`; }
    13→export function blockIndex(lx: number, y: number, lz: number): number {
    14→  return lx + y * CHUNK_SIZE + lz * CHUNK_SIZE * WORLD_HEIGHT;
    15→}
    16→
    17→const terrainNoise = createNoise2D();
    18→const terrainNoise2 = createNoise2D();
    19→const terrainNoise3 = createNoise2D();
    20→const biomeNoise    = createNoise2D();
    21→const oreNoise      = createNoise2D();
    22→
    23→function pseudoRand(seed: number): number {
    24→  const s = Math.sin(seed * 7919.131 + 2147.483) * 43758.5453;
    25→  return s - Math.floor(s);
    26→}
    27→
    28→function getBiome(wx: number, wz: number): Biome {
    29→  const n = biomeNoise(wx * 0.003, wz * 0.003);
    30→  return Math.min(9, Math.floor((n + 1) / 2 * 10)) as Biome;
    31→}
    32→
    33→function getTerrainHeightAtPoint(wx: number, wz: number, def: BiomeDef): number {
    34→  const n1 = terrainNoise(wx * 0.012, wz * 0.012);
    35→  const n2 = terrainNoise2(wx * 0.04, wz * 0.04) * 0.5;
    36→  const n3 = terrainNoise3(wx * 0.09, wz * 0.09) * 0.25;
    37→  return Math.floor(def.baseHeight + (n1 + n2 + n3) * def.heightVariation);
    38→}
    39→
    40→// Biome structures mapping
    41→const BIOME_STRUCTURES: Record<Biome, StructureKey[]> = {
    42→  [Biome.PLAINS]:    ['OAK_HOUSE','VILLAGE_WELL','STONE_CIRCLE','GRAVEYARD','OUTPOST_TOWER'],
    43→  [Biome.FOREST]:    ['OAK_HOUSE','ANCIENT_LIBRARY','MUSHROOM_HOLLOW','RUINED_TOWER'],
    44→  [Biome.DESERT]:    ['DESERT_PYRAMID','DESERT_WELL','MESA_RUIN'],
    45→  [Biome.OCEAN]:     ['UNDERWATER_RUIN','OCEAN_MONUMENT'],
    46→  [Biome.TAIGA]:     ['TAIGA_CABIN','IGLOO','OUTPOST_TOWER','STONE_CIRCLE'],
    47→  [Biome.JUNGLE]:    ['JUNGLE_TEMPLE','MUSHROOM_HOLLOW','ANCIENT_LIBRARY'],
    48→  [Biome.SAVANNA]:   ['OAK_HOUSE','OUTPOST_TOWER','GRAVEYARD','STONE_CIRCLE'],
    49→  [Biome.SWAMP]:     ['SWAMP_HUT','GRAVEYARD','MUSHROOM_HOLLOW'],
    50→  [Biome.MOUNTAINS]: ['STONE_TOWER','RUINED_TOWER','MONOLITH','BEACON_SHRINE'],
    51→  [Biome.MESA]:      ['MESA_RUIN','STONE_CIRCLE','BLACKSTONE_FORT','NETHER_SHRINE'],
    52→};
    53→
    54→function generateChunk(cx: number, cz: number): ChunkData {
    55→  const data = new Uint8Array(CHUNK_SIZE * WORLD_HEIGHT * CHUNK_SIZE);
    56→
    57→  // Determine the dominant biome for this chunk (center point)
    58→  const chunkCenterX = cx * CHUNK_SIZE + CHUNK_SIZE / 2;
    59→  const chunkCenterZ = cz * CHUNK_SIZE + CHUNK_SIZE / 2;
    60→  const chunkBiome = getBiome(chunkCenterX, chunkCenterZ);
    61→  const def = BIOME_DEFS[chunkBiome];
    62→
    63→  for (let lx = 0; lx < CHUNK_SIZE; lx++) {
    64→    for (let lz = 0; lz < CHUNK_SIZE; lz++) {
    65→      const wx = cx * CHUNK_SIZE + lx;
    66→      const wz = cz * CHUNK_SIZE + lz;
    67→      const biome = getBiome(wx, wz);
    68→      const bd = BIOME_DEFS[biome];
    69→      const height = Math.max(1, getTerrainHeightAtPoint(wx, wz, bd));
    70→
    71→      for (let y = 0; y < WORLD_HEIGHT; y++) {
    72→        const idx = blockIndex(lx, y, lz);
    73→        if (y === 0) {
    74→          data[idx] = BlockType.BEDROCK;
    75→        } else if (y < height - 4) {
    76→          // Ore generation
    77→          const ore = oreNoise(wx * 0.25 + y * 0.7, wz * 0.25);
    78→          if (y < 16 && ore > 0.72)       data[idx] = BlockType.COAL_ORE;
    79→          else if (y < 30 && ore > 0.78)  data[idx] = BlockType.IRON_ORE;
    80→          else if (y < 20 && ore > 0.82)  data[idx] = BlockType.GOLD_ORE;
    81→          else if (y < 12 && ore > 0.86)  data[idx] = BlockType.DIAMOND_ORE;
    82→          else if (y < 32 && ore > 0.84)  data[idx] = BlockType.COPPER_ORE;
    83→          else if (y < 24 && ore > 0.88)  data[idx] = BlockType.EMERALD_ORE;
    84→          else if (y < 16 && ore > 0.90)  data[idx] = BlockType.LAPIS_ORE;
    85→          else if (y < 16 && ore > 0.92)  data[idx] = BlockType.REDSTONE_ORE;
    86→          else if (y < 8)                 data[idx] = biome === Biome.MOUNTAINS ? BlockType.DEEPSLATE : BlockType.STONE;
    87→          else                             data[idx] = BlockType.STONE;
    88→        } else if (y < height) {
    89→          data[idx] = bd.subSurfaceBlock;
    90→        } else if (y === height) {
    91→          if (biome === Biome.MOUNTAINS && height > 28) data[idx] = BlockType.SNOW_BLOCK;
    92→          else if (biome === Biome.TAIGA && height > 22) data[idx] = BlockType.SNOW_BLOCK;
    93→          else data[idx] = bd.surfaceBlock;
    94→        } else if (y <= SEA_LEVEL) {
    95→          data[idx] = biome === Biome.OCEAN ? BlockType.WATER : bd.seaFillBlock;
    96→        } else {
    97→          data[idx] = BlockType.AIR;
    98→        }
    99→      }
   100→
   101→      // Tree generation
   102→      if (bd.treeDensity > 0 && height > SEA_LEVEL && lx >= 2 && lx <= CHUNK_SIZE - 3 && lz >= 2 && lz <= CHUNK_SIZE - 3) {
   103→        const treeRoll = pseudoRand(wx * 1234.567 + wz * 89.123);
   104→        if (treeRoll < bd.treeDensity) {
   105→          if (biome === Biome.DESERT) {
   106→            // Cactus
   107→            const cactusH = 2 + Math.floor(pseudoRand(wx + wz * 3) * 3);
   108→            for (let ty = 1; ty <= cactusH; ty++) {
   109→              const y = height + ty;
   110→              if (y < WORLD_HEIGHT) data[blockIndex(lx, y, lz)] = BlockType.CACTUS;
   111→            }
   112→          } else {
   113→            const trunkH = bd.treeTrunkMin + Math.floor(pseudoRand(wx * 3 + wz) * (bd.treeTrunkMax - bd.treeTrunkMin + 1));
   114→            // Trunk
   115→            for (let ty = 1; ty <= trunkH; ty++) {
   116→              const y = height + ty;
   117→              if (y < WORLD_HEIGHT) data[blockIndex(lx, y, lz)] = bd.treeLog;
   118→            }
   119→            // Leaves
   120→            if (bd.treeLeafRadius > 0) {
   121→              for (let ly = trunkH - 1; ly <= trunkH + 1; ly++) {
   122→                const radius = ly <= trunkH ? bd.treeLeafRadius : Math.max(1, bd.treeLeafRadius - 1);
   123→                for (let dx = -radius; dx <= radius; dx++) {
   124→                  for (let dz2 = -radius; dz2 <= radius; dz2++) {
   125→                    if (Math.abs(dx) === radius && Math.abs(dz2) === radius) continue;
   126→                    const nlx = lx + dx; const nlz = lz + dz2;
   127→                    const ny = height + ly;
   128→                    if (nlx >= 0 && nlx < CHUNK_SIZE && nlz >= 0 && nlz < CHUNK_SIZE && ny < WORLD_HEIGHT) {
   129→                      if (data[blockIndex(nlx, ny, nlz)] === BlockType.AIR) {
   130→                        data[blockIndex(nlx, ny, nlz)] = bd.treeLeaf;
   131→                      }
   132→                    }
   133→                  }
   134→                }
   135→              }
   136→            }
   137→          }
   138→        }
   139→      }
   140→    }
   141→  }
   142→
   143→  // Structure placement
   144→  const structureRoll = pseudoRand(cx * 7919 + cz * 3571);
   145→  if (structureRoll > 0.90) {
   146→    const options = BIOME_STRUCTURES[chunkBiome];
   147→    const sIdx = Math.floor(pseudoRand(cx * 13 + cz * 17) * options.length);
   148→    const structureKey = options[sIdx];
   149→    const generator = STRUCTURE_GENERATORS[structureKey];
   150→
   151→    // Base position at chunk center surface
   152→    const sCx = cx * CHUNK_SIZE + 4;
   153→    const sCz = cz * CHUNK_SIZE + 4;
   154→    // Find height at that point
   155→    const sBiome = getBiome(sCx, sCz);
   156→    const sDef = BIOME_DEFS[sBiome];
   157→    const sH = getTerrainHeightAtPoint(sCx, sCz, sDef);
   158→
   159→    // For dungeon: place underground
   160→    const baseY = structureKey === 'DUNGEON' ? Math.max(5, sH - 8) : structureKey === 'UNDERWATER_RUIN' || structureKey === 'OCEAN_MONUMENT' ? Math.max(1, sH - 2) : sH;
   161→
   162→    const placements: BP[] = generator(sCx, baseY, sCz);
   163→    placements.forEach(([wx, wy, wz, type]) => {
   164→      const lx = wx - cx * CHUNK_SIZE;
   165→      const lz = wz - cz * CHUNK_SIZE;
   166→      if (lx < 0 || lx >= CHUNK_SIZE || lz < 0 || lz >= CHUNK_SIZE) return;
   167→      if (wy < 0 || wy >= WORLD_HEIGHT) return;
   168→      data[blockIndex(lx, wy, lz)] = type;
   169→    });
   170→  }
   171→
   172→  return data;
   173→}
