   175→class WorldManager {
   176→  chunks = new Map<string, ChunkData>();
   177→  dirtyChunks = new Set<string>();
   178→
   179→  getOrGenerateChunk(cx: number, cz: number): ChunkData {
   180→    const key = getChunkKey(cx, cz);
   181→    let chunk = this.chunks.get(key);
   182→    if (!chunk) { chunk = generateChunk(cx, cz); this.chunks.set(key, chunk); }
   183→    return chunk;
   184→  }
   185→
   186→  getBlock(x: number, y: number, z: number): BlockType {
   187→    if (y < 0) return BlockType.BEDROCK;
   188→    if (y >= WORLD_HEIGHT) return BlockType.AIR;
   189→    const cx = Math.floor(x / CHUNK_SIZE);
   190→    const cz = Math.floor(z / CHUNK_SIZE);
   191→    const chunk = this.getOrGenerateChunk(cx, cz);
   192→    const lx = ((x % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
   193→    const lz = ((z % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
   194→    return chunk[blockIndex(lx, y, lz)];
   195→  }
   196→
   197→  setBlock(x: number, y: number, z: number, type: BlockType): void {
   198→    if (y < 0 || y >= WORLD_HEIGHT) return;
   199→    const cx = Math.floor(x / CHUNK_SIZE);
   200→    const cz = Math.floor(z / CHUNK_SIZE);
   201→    const chunk = this.getOrGenerateChunk(cx, cz);
   202→    const lx = ((x % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
   203→    const lz = ((z % CHUNK_SIZE) + CHUNK_SIZE) % CHUNK_SIZE;
   204→    chunk[blockIndex(lx, y, lz)] = type;
   205→    this.dirtyChunks.add(getChunkKey(cx, cz));
   206→    if (lx === 0) this.dirtyChunks.add(getChunkKey(cx-1, cz));
   207→    if (lx === CHUNK_SIZE-1) this.dirtyChunks.add(getChunkKey(cx+1, cz));
   208→    if (lz === 0) this.dirtyChunks.add(getChunkKey(cx, cz-1));
   209→    if (lz === CHUNK_SIZE-1) this.dirtyChunks.add(getChunkKey(cx, cz+1));
   210→  }
   211→
   212→  getTerrainHeight(x: number, z: number): number {
   213→    for (let y = WORLD_HEIGHT - 1; y >= 0; y--) {
   214→      if (isSolid(this.getBlock(x, y, z))) return y;
   215→    }
   216→    return 0;
   217→  }
   218→}
   219→
   220→export const worldManager = new WorldManager();
