     1→import { useRef, useEffect } from 'react';
     2→
     3→export interface TouchState {
     4→  dx: number; dz: number;
     5→  jump: boolean; doBreak: boolean; doPlace: boolean;
     6→  flyDown: boolean; toggleMode: boolean;
     7→  lookDx: number; lookDy: number;
     8→}
