    10→export function createTouchState(): TouchState {
    11→  return { dx:0, dz:0, jump:false, doBreak:false, doPlace:false, flyDown:false, toggleMode:false, lookDx:0, lookDy:0 };
    12→}
    13→
    14→interface Props { stateRef: React.MutableRefObject<TouchState>; }
    15→
    16→const RADIUS = 52;
    17→
    18→export default function TouchControls({ stateRef }: Props) {
    19→  const baseRef    = useRef<HTMLDivElement>(null);
    20→  const thumbRef   = useRef<HTMLDivElement>(null);
    21→  const joyTouchId = useRef<number | null>(null);
    22→  const joyCenter  = useRef({ x: 0, y: 0 });
    23→  const lookTouchId = useRef<number | null>(null);
    24→  const lookPrev    = useRef({ x: 0, y: 0 });
    25→
    26→  useEffect(() => {
    27→    const base = baseRef.current;
    28→    if (!base) return;
    29→
    30→    // ─── Joystick listeners (on the joystick element only) ───────────
    31→    const joyStart = (e: TouchEvent) => {
    32→      e.stopPropagation();
    33→      if (joyTouchId.current !== null) return;
    34→      const t = e.changedTouches[0];
    35→      const r = base.getBoundingClientRect();
    36→      joyTouchId.current = t.identifier;
    37→      joyCenter.current  = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    38→    };
    39→
    40→    const joyMove = (e: TouchEvent) => {
    41→      for (let i = 0; i < e.changedTouches.length; i++) {
    42→        const t = e.changedTouches[i];
    43→        if (t.identifier !== joyTouchId.current) continue;
    44→        const rx = t.clientX - joyCenter.current.x;
    45→        const ry = t.clientY - joyCenter.current.y;
    46→        const len = Math.sqrt(rx*rx + ry*ry);
    47→        const c = Math.min(len, RADIUS);
    48→        const nx = len > 0 ? rx / len * c / RADIUS : 0;
    49→        const ny = len > 0 ? ry / len * c / RADIUS : 0;
    50→        stateRef.current.dx = nx;
    51→        stateRef.current.dz = ny;          // positive ny = down = backward
    52→        if (thumbRef.current) thumbRef.current.style.transform = `translate(${nx*RADIUS}px,${ny*RADIUS}px)`;
    53→      }
    54→    };
    55→
    56→    const joyEnd = (e: TouchEvent) => {
    57→      for (let i = 0; i < e.changedTouches.length; i++) {
    58→        if (e.changedTouches[i].identifier === joyTouchId.current) {
    59→          joyTouchId.current = null;
    60→          stateRef.current.dx = 0; stateRef.current.dz = 0;
    61→          if (thumbRef.current) thumbRef.current.style.transform = '';
    62→        }
    63→      }
    64→    };
    65→
    66→    base.addEventListener('touchstart', joyStart, { passive: true });
