    35→function collidesAt(pos: THREE.Vector3): boolean {
    36→  const hw = PLAYER_W / 2;
    37→  const x0 = Math.floor(pos.x - hw), x1 = Math.floor(pos.x + hw - 0.001);
    38→  const y0 = Math.floor(pos.y),      y1 = Math.floor(pos.y + PLAYER_H - 0.001);
    39→  const z0 = Math.floor(pos.z - hw), z1 = Math.floor(pos.z + hw - 0.001);
    40→  for (let bx = x0; bx <= x1; bx++)
    41→    for (let by = y0; by <= y1; by++)
    42→      for (let bz = z0; bz <= z1; bz++)
