    47→function castRay(origin: THREE.Vector3, dir: THREE.Vector3, maxD: number) {
    48→  const d = dir.clone().normalize();
    49→  let bx = Math.floor(origin.x), by = Math.floor(origin.y), bz = Math.floor(origin.z);
    50→  const sx = d.x > 0 ? 1 : -1, sy = d.y > 0 ? 1 : -1, sz = d.z > 0 ? 1 : -1;
    51→  const dtx = d.x !== 0 ? Math.abs(1/d.x) : Infinity;
    52→  const dty = d.y !== 0 ? Math.abs(1/d.y) : Infinity;
    53→  const dtz = d.z !== 0 ? Math.abs(1/d.z) : Infinity;
    54→  let tmx = d.x !== 0 ? (sx>0 ? Math.ceil(origin.x)-origin.x : origin.x-Math.floor(origin.x)) / Math.abs(d.x) : Infinity;
    55→  let tmy = d.y !== 0 ? (sy>0 ? Math.ceil(origin.y)-origin.y : origin.y-Math.floor(origin.y)) / Math.abs(d.y) : Infinity;
    56→  let tmz = d.z !== 0 ? (sz>0 ? Math.ceil(origin.z)-origin.z : origin.z-Math.floor(origin.z)) / Math.abs(d.z) : Infinity;
    57→  if (tmx === 0) tmx = dtx; if (tmy === 0) tmy = dty; if (tmz === 0) tmz = dtz;
    58→  let pbx = bx, pby = by, pbz = bz, nx = 0, ny = 0, nz = 0, t = 0;
    59→  while (t < maxD) {
    60→    if (isSolid(worldManager.getBlock(bx, by, bz)))
    61→      return { hit:true, hitPos:new THREE.Vector3(bx,by,bz), prevPos:new THREE.Vector3(pbx,pby,pbz), normal:new THREE.Vector3(nx,ny,nz), dist:t };
    62→    pbx=bx; pby=by; pbz=bz;
    63→    if (tmx<tmy && tmx<tmz) { t=tmx; bx+=sx; tmx+=dtx; nx=-sx; ny=0; nz=0; }
    64→    else if (tmy<tmz)        { t=tmy; by+=sy; tmy+=dty; nx=0; ny=-sy; nz=0; }
    65→    else                      { t=tmz; bz+=sz; tmz+=dtz; nx=0; ny=0; nz=-sz; }
    66→  }
    67→  return { hit:false, hitPos:null, prevPos:null, normal:null, dist:maxD };
    68→}
