import { useState, useMemo } from 'react';
import { BlockType, BLOCK_COLORS, BLOCK_NAMES } from './blocks';

interface Props {
  mode: 'CREATIVE' | 'SURVIVAL';
  counts: Record<number, number>;
  hotbar: BlockType[];
  selectedSlot: number;
  onAssign: (slot: number, type: BlockType) => void;
  onClose: () => void;
}

function colorStr(t: BlockType): string {
  const c = BLOCK_COLORS[t];
  if (!c) return '#555';
  return `rgb(${Math.round(c[0]*255)},${Math.round(c[1]*255)},${Math.round(c[2]*255)})`;
}

type Cat = 'all' | 'natural' | 'stone' | 'wood' | 'ores' | 'building' | 'color' | 'special';

function getBlockCat(t: BlockType): Cat {
  if (t >= 1  && t <= 14)  return 'natural';
  if (t >= 15 && t <= 34)  return 'stone';
  if (t >= 35 && t <= 54)  return 'wood';
  if (t >= 55 && t <= 77)  return 'ores';
  if (t >= 78 && t <= 126) return 'natural';
  if (t >= 127 && t <= 167) return 'color';
  if (t >= 168 && t <= 225) return 'building';
  return 'special';
}

const ALL_BLOCKS: BlockType[] = Array.from({ length: 225 }, (_, i) => i + 1) as BlockType[];
const CATS: { key: Cat; label: string }[] = [
  { key: 'all',      label: 'All'      },
  { key: 'natural',  label: 'Natural'  },
  { key: 'stone',    label: 'Stone'    },
  { key: 'wood',     label: 'Wood'     },
  { key: 'ores',     label: 'Ores'     },
  { key: 'color',    label: 'Color'    },
  { key: 'building', label: 'Special'  },
];

export default function Inventory({ mode, counts, hotbar, selectedSlot, onAssign, onClose }: Props) {
  const [cat,    setCat]    = useState<Cat>('all');
  const [search, setSearch] = useState('');
  const [pickedSlot, setPickedSlot] = useState(selectedSlot);

  const blocks = useMemo(() => {
    const q = search.toLowerCase();
    return ALL_BLOCKS.filter(t => {
      if (mode === 'SURVIVAL' && (counts[t] || 0) === 0) return false;
      if (cat !== 'all' && getBlockCat(t) !== cat) return false;
      if (q && !(BLOCK_NAMES[t] ?? '').toLowerCase().includes(q)) return false;
      return true;
    });
  }, [mode, counts, cat, search]);

  const assign = (type: BlockType) => {
    onAssign(pickedSlot, type);
  };

  return (
    <div
      data-no-look="1"
      style={{
        position:'fixed', inset:0, zIndex:60,
        background:'rgba(0,0,0,0.82)',
        display:'flex', alignItems:'center', justifyContent:'center',
      }}
      onClick={onClose}
    >
      <div
        data-no-look="1"
        onClick={e => e.stopPropagation()}
        style={{
          background:'#12122a', border:'2px solid #4488cc',
          borderRadius:14, padding:16, width:460, maxWidth:'97vw',
          maxHeight:'92vh', display:'flex', flexDirection:'column', gap:10,
          color:'#fff', fontFamily:'"Courier New",monospace',
          overflow:'hidden',
        }}
      >
        {/* Header */}
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div style={{ fontSize:18, fontWeight:700, color:'#4ac', letterSpacing:2 }}>
            📦 {mode === 'CREATIVE' ? 'BLOCK PICKER' : 'INVENTORY'}
          </div>
          <div onClick={onClose} style={{ cursor:'pointer', fontSize:20, color:'#aaa', padding:'0 4px' }}>✕</div>
        </div>

        {/* Hotbar slot selector */}
        <div style={{ fontSize:10, color:'#888', marginBottom:2 }}>
          Tap a hotbar slot to select it, then click a block below to assign it:
        </div>
        <div style={{ display:'flex', gap:4 }}>
          {hotbar.map((b, i) => (
            <div
              key={i}
              onClick={() => setPickedSlot(i)}
              style={{
                flex:1, height:44, borderRadius:6, cursor:'pointer',
                border: i === pickedSlot ? '2px solid #ffe030' : '2px solid rgba(255,255,255,0.18)',
                background: i === pickedSlot ? 'rgba(255,224,48,0.15)' : 'rgba(0,0,0,0.4)',
                display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:2,
              }}
            >
              <div style={{
                width:22, height:22, borderRadius:3,
                background: b !== BlockType.AIR ? colorStr(b) : 'rgba(255,255,255,0.08)',
                border:'1px solid rgba(0,0,0,0.4)',
              }} />
              <div style={{ fontSize:7, color:'rgba(255,255,255,0.4)' }}>{i+1}</div>
            </div>
          ))}
        </div>

        {/* Category tabs */}
        <div style={{ display:'flex', gap:4, flexWrap:'wrap' }}>
          {CATS.map(c => (
            <div key={c.key} onClick={() => setCat(c.key)} style={{
              padding:'3px 9px', borderRadius:6, fontSize:10, cursor:'pointer',
              background: cat === c.key ? '#4488cc' : '#222',
              color: cat === c.key ? '#fff' : '#aaa',
              fontWeight:700,
            }}>
              {c.label}
            </div>
          ))}
        </div>

        {/* Search */}
        <input
          type="text"
          placeholder="Search blocks…"
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{
            background:'#1a1a3a', border:'1px solid #444', borderRadius:6,
            color:'#fff', padding:'6px 10px', fontSize:12, outline:'none',
            fontFamily:'"Courier New",monospace',
          }}
        />

        {/* Count */}
        <div style={{ fontSize:10, color:'#666' }}>
          {mode === 'SURVIVAL'
            ? `${blocks.length} block types owned`
            : `${blocks.length} blocks available`
          }
        </div>

        {/* Block grid */}
        <div style={{
          overflowY:'auto', display:'grid',
          gridTemplateColumns:'repeat(auto-fill, minmax(68px, 1fr))', gap:6,
        }}>
          {blocks.map(t => {
            const cnt = counts[t];
            const name = BLOCK_NAMES[t] ?? `#${t}`;
            return (
              <div
                key={t}
                onClick={() => assign(t)}
                style={{
                  display:'flex', flexDirection:'column', alignItems:'center',
                  padding:'6px 4px', borderRadius:8, cursor:'pointer',
                  background:'rgba(255,255,255,0.05)',
                  border:'1px solid rgba(255,255,255,0.12)',
                  gap:4, transition:'background 0.1s',
                }}
                onMouseEnter={e => (e.currentTarget.style.background='rgba(68,136,204,0.3)')}
                onMouseLeave={e => (e.currentTarget.style.background='rgba(255,255,255,0.05)')}
              >
                <div style={{
                  width:36, height:36, borderRadius:5,
                  background: colorStr(t),
                  border:'1px solid rgba(0,0,0,0.5)',
                  boxShadow:'inset -2px -2px 5px rgba(0,0,0,0.3), inset 2px 2px 5px rgba(255,255,255,0.15)',
                  position:'relative',
                }}>
                  {cnt !== undefined && cnt > 0 && (
                    <div style={{
                      position:'absolute', bottom:-2, right:-2,
                      background:'#333', color:'#fff', fontSize:8,
                      padding:'1px 3px', borderRadius:3, fontWeight:700,
                    }}>{cnt}</div>
                  )}
                </div>
                <div style={{
                  fontSize:7, textAlign:'center', color:'#ccc', lineHeight:1.2,
                  maxWidth:64, overflow:'hidden',
                  display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical',
                }}>
                  {name}
                </div>
              </div>
            );
          })}
          {blocks.length === 0 && (
            <div style={{ gridColumn:'1/-1', textAlign:'center', color:'#555', padding:20, fontSize:12 }}>
              {mode === 'SURVIVAL' ? 'Mine blocks to fill your inventory!' : 'No blocks match.'}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { BlockType, BLOCK_COLORS, BLOCK_NAMES } from './blocks';

interface HUDProps {
  mode: 'CREATIVE' | 'SURVIVAL';
  health: number;
  hunger: number;
  hotbar: BlockType[];
  counts: Record<number, number>;
  selectedSlot: number;
  pos: { x: number; y: number; z: number };
  onSlotSelect: (i: number) => void;
  onOpenInventory: () => void;
}

function colorStyle(type: BlockType): string {
  if (type === BlockType.AIR) return 'rgba(255,255,255,0.08)';
  const [r, g, b] = BLOCK_COLORS[type];
  return `rgb(${Math.round(r*255)},${Math.round(g*255)},${Math.round(b*255)})`;
}

function HeartRow({ val, max, color }: { val: number; max: number; color: string }) {
  return (
    <div style={{ display: 'flex', gap: 2, flexWrap: 'wrap', maxWidth: 160 }}>
      {Array.from({ length: Math.ceil(max / 2) }).map((_, i) => {
        const full = val >= (i+1)*2;
        const half = !full && val >= i*2+1;
        return (
          <div key={i} style={{
            width: 12, height: 12, borderRadius: 2, border: '1px solid rgba(0,0,0,0.5)',
            background: full ? color : half ? color + '88' : 'rgba(0,0,0,0.5)',
          }} />
        );
      })}
    </div>
  );
}

export default function HUD({ mode, health, hunger, hotbar, counts, selectedSlot, pos, onSlotSelect, onOpenInventory }: HUDProps) {
  return (
    <div style={{
      position: 'absolute', inset: 0, zIndex: 10,
      fontFamily: '"Courier New", monospace', userSelect: 'none',
      pointerEvents: 'none',
    }}>
      {/* Crosshair */}
      <div style={{
        position: 'absolute', top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)', width: 24, height: 24,
        pointerEvents: 'none',
      }}>
        <div style={{ position:'absolute', top:'50%', left:0, right:0, height:2, background:'rgba(255,255,255,0.85)', marginTop:-1, boxShadow:'0 0 2px #000' }} />
        <div style={{ position:'absolute', left:'50%', top:0, bottom:0, width:2, background:'rgba(255,255,255,0.85)', marginLeft:-1, boxShadow:'0 0 2px #000' }} />
      </div>

      {/* Top-left: health + coords */}
      <div style={{
        position: 'absolute', top: 10, left: 10,
        color: '#fff', fontSize: 12, display: 'flex', flexDirection: 'column', gap: 6,
        pointerEvents: 'none',
      }}>
        {mode === 'SURVIVAL' && (
          <>
            <div>
              <div style={{ fontSize: 10, color: '#ccc', marginBottom: 2 }}>HEALTH</div>
              <HeartRow val={health} max={20} color="#ff3333" />
            </div>
            <div>
              <div style={{ fontSize: 10, color: '#ccc', marginBottom: 2 }}>HUNGER</div>
              <HeartRow val={Math.round(hunger)} max={20} color="#cc8800" />
            </div>
          </>
        )}
        <div style={{
          background: 'rgba(0,0,0,0.55)', padding: '3px 6px', borderRadius: 3, fontSize: 11,
        }}>
          X:{Math.floor(pos.x)} Y:{Math.floor(pos.y)} Z:{Math.floor(pos.z)}
        </div>
      </div>

      {/* Top-right: mode badge */}
      <div style={{
        position: 'absolute', top: 10, right: 10,
        background: mode === 'CREATIVE' ? 'rgba(0,100,220,0.75)' : 'rgba(180,40,40,0.75)',
        color: '#fff', fontSize: 11, fontWeight: 'bold',
        padding: '4px 10px', borderRadius: 4, letterSpacing: 1,
        boxShadow: '0 2px 6px rgba(0,0,0,0.4)',
        pointerEvents: 'none',
      }}>
        {mode}
      </div>

      {/* Bottom: hotbar — interactive */}
      <div style={{
        position: 'absolute', bottom: 14, left: '50%',
        transform: 'translateX(-50%)',
        display: 'flex', gap: 3,
        background: 'rgba(0,0,0,0.6)', padding: '4px 5px', borderRadius: 5,
        boxShadow: '0 2px 8px rgba(0,0,0,0.5)',
        pointerEvents: 'auto',
      }}>
        {hotbar.map((block, i) => {
          const cnt = counts[block];
          const hasCnt = mode === 'SURVIVAL' && block !== BlockType.AIR && cnt !== undefined;
          return (
            <div
              key={i}
              data-touch-btn="1"
              onTouchStart={e => { e.stopPropagation(); onSlotSelect(i); }}
              onClick={() => onSlotSelect(i)}
              style={{
                width: 48, height: 48,
                border: i === selectedSlot ? '2px solid #ffe030' : '2px solid rgba(255,255,255,0.25)',
                background: i === selectedSlot ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.5)',
                borderRadius: 4,
                display: 'flex', flexDirection: 'column',
                alignItems: 'center', justifyContent: 'center',
                gap: 1, transition: 'border-color 0.1s',
                boxShadow: i === selectedSlot ? '0 0 0 1px rgba(255,224,48,0.4) inset' : 'none',
                cursor: 'pointer', position: 'relative',
              }}
            >
              <div style={{
                width: 30, height: 30, borderRadius: 3,
                background: colorStyle(block),
                border: '1px solid rgba(0,0,0,0.4)',
                boxShadow: block !== BlockType.AIR ? 'inset -2px -2px 4px rgba(0,0,0,0.3), inset 2px 2px 4px rgba(255,255,255,0.15)' : 'none',
              }} />
              {block !== BlockType.AIR && (
                <div style={{ color: '#ddd', fontSize: 7, textAlign: 'center', lineHeight: 1 }}>
                  {(BLOCK_NAMES[block] ?? '').slice(0, 7)}
                </div>
              )}
              <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 7 }}>{i + 1}</div>
              {hasCnt && (
                <div style={{
                  position:'absolute', top:2, right:3,
                  fontSize:8, fontWeight:700, color:'#ffe',
                  textShadow:'0 0 3px #000',
                }}>
                  {cnt}
                </div>
              )}
            </div>
          );
        })}

        {/* Inventory button */}
        <div
          data-touch-btn="1"
          onTouchStart={e => { e.stopPropagation(); onOpenInventory(); }}
          onClick={onOpenInventory}
          style={{
            width:36, height:48, borderRadius:4, cursor:'pointer',
            border:'2px solid rgba(68,136,204,0.6)',
            background:'rgba(10,30,60,0.7)',
            display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
            gap:2, marginLeft:4,
          }}
        >
          <div style={{ fontSize:16 }}>📦</div>
          <div style={{ fontSize:7, color:'#7ac' }}>I</div>
        </div>
      </div>

      {/* Controls hint */}
      <div style={{
        position: 'absolute', bottom: 72, left: '50%',
        transform: 'translateX(-50%)',
        color: 'rgba(255,255,255,0.35)', fontSize: 9, textAlign: 'center', whiteSpace: 'nowrap',
        pointerEvents: 'none',
      }}>
        WASD · Space: Jump · 1–9: Hotbar · E: Craft · I: Inventory · Tab: Mode
      </div>
    </div>
  );
}

