import { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { useKeyboardControls } from '@react-three/drei';
import * as THREE from 'three';
import { Controls } from './Game';
import { worldManager, CHUNK_SIZE } from './worldGen';
import { BlockType, isSolid } from './blocks';
import { raycastMobs, damageMob } from './mobSystem';
import type { TouchState } from './TouchControls';

const SPEED          = 5;
const CREATIVE_SPEED = 8;
const FLY_SPEED      = 12;
const JUMP_FORCE     = 7;
const GRAVITY        = 22;
const PLAYER_H       = 1.8;
const PLAYER_W       = 0.58;
const EYE_H          = 1.6;
const MAX_REACH_CREATIVE = 6;
const MAX_REACH_SURVIVAL = 4;
const BREAK_TIME_MS  = 900;

interface PlayerProps {
  mode:           'CREATIVE' | 'SURVIVAL';
  setMode:        (m: 'CREATIVE' | 'SURVIVAL') => void;
  playerChunkRef: React.MutableRefObject<{ x: number; z: number }>;
  onStateChange:  (s: {
    health: number; hunger: number;
    hotbar: BlockType[]; selectedSlot: number;
    pos: THREE.Vector3;
  }) => void;
  touchRef:       React.MutableRefObject<TouchState>;
  externalSlot:   number;
  externalHotbar: BlockType[];
  canPlace:       (type: BlockType) => boolean;
  onBlockBreak:   (type: BlockType) => void;
  onBlockPlace:   (type: BlockType) => void;
  onChestOpen?:   (x: number, y: number, z: number) => void;
  isDead?:        boolean;
  respawnTrigger?: number;
}

function collidesAt(pos: THREE.Vector3): boolean {
  const hw = PLAYER_W / 2;
  const x0 = Math.floor(pos.x - hw), x1 = Math.floor(pos.x + hw - 0.001);
  const y0 = Math.floor(pos.y),      y1 = Math.floor(pos.y + PLAYER_H - 0.001);
  const z0 = Math.floor(pos.z - hw), z1 = Math.floor(pos.z + hw - 0.001);
  for (let bx = x0; bx <= x1; bx++)
    for (let by = y0; by <= y1; by++)
      for (let bz = z0; bz <= z1; bz++)
        if (isSolid(worldManager.getBlock(bx, by, bz))) return true;
  return false;
}

function castRay(origin: THREE.Vector3, dir: THREE.Vector3, maxD: number) {
  const d = dir.clone().normalize();
  let bx = Math.floor(origin.x), by = Math.floor(origin.y), bz = Math.floor(origin.z);
  const sx = d.x > 0 ? 1 : -1, sy = d.y > 0 ? 1 : -1, sz = d.z > 0 ? 1 : -1;
  const dtx = d.x !== 0 ? Math.abs(1/d.x) : Infinity;
  const dty = d.y !== 0 ? Math.abs(1/d.y) : Infinity;
  const dtz = d.z !== 0 ? Math.abs(1/d.z) : Infinity;
  let tmx = d.x !== 0 ? (sx>0 ? Math.ceil(origin.x)-origin.x : origin.x-Math.floor(origin.x)) / Math.abs(d.x) : Infinity;
  let tmy = d.y !== 0 ? (sy>0 ? Math.ceil(origin.y)-origin.y : origin.y-Math.floor(origin.y)) / Math.abs(d.y) : Infinity;
  let tmz = d.z !== 0 ? (sz>0 ? Math.ceil(origin.z)-origin.z : origin.z-Math.floor(origin.z)) / Math.abs(d.z) : Infinity;
  if (tmx === 0) tmx = dtx; if (tmy === 0) tmy = dty; if (tmz === 0) tmz = dtz;
  let pbx = bx, pby = by, pbz = bz, nx = 0, ny = 0, nz = 0, t = 0;
  while (t < maxD) {
    if (isSolid(worldManager.getBlock(bx, by, bz)))
      return { hit:true, hitPos:new THREE.Vector3(bx,by,bz), prevPos:new THREE.Vector3(pbx,pby,pbz), normal:new THREE.Vector3(nx,ny,nz), dist:t };
    pbx=bx; pby=by; pbz=bz;
    if (tmx<tmy && tmx<tmz) { t=tmx; bx+=sx; tmx+=dtx; nx=-sx; ny=0;  nz=0; }
    else if (tmy<tmz)        { t=tmy; by+=sy; tmy+=dty; nx=0;  ny=-sy; nz=0; }
    else                      { t=tmz; bz+=sz; tmz+=dtz; nx=0;  ny=0;  nz=-sz; }
  }
  return { hit:false, hitPos:null, prevPos:null, normal:null, dist:maxD };
}

export default function Player({
  mode, setMode, playerChunkRef, onStateChange,
  touchRef, externalSlot, externalHotbar,
  canPlace, onBlockBreak, onBlockPlace, onChestOpen,
  isDead = false, respawnTrigger = 0,
}: PlayerProps) {
  const { camera, gl } = useThree();
  const [, getKeys] = useKeyboardControls<Controls>();

  const pos          = useRef(new THREE.Vector3(8, 30, 8));
  const vel          = useRef(new THREE.Vector3());
  const yaw          = useRef(0);
  const pitch        = useRef(0);
  const grounded     = useRef(false);
  const flying       = useRef(mode === 'CREATIVE');
  const modeRef      = useRef(mode);
  const hotbar       = useRef<BlockType[]>([...externalHotbar]);
  const slot         = useRef(0);
  const health       = useRef(20);
  const hunger       = useRef(20);
  const lmbDown      = useRef(false);
  const rmbDown      = useRef(false);
  const breakStart   = useRef(0);
  const breakPos     = useRef<THREE.Vector3 | null>(null);
  const lastPlace    = useRef(0);
  const stateT       = useRef(0);
  const spaceLastTap = useRef(0);
  const prevMode     = useRef(mode);
  const dir3         = useRef(new THREE.Vector3());
  const eyePos       = useRef(new THREE.Vector3());
  const tmpPos       = useRef(new THREE.Vector3());
  const lastHit      = useRef(0);
  const prevToggle   = useRef(false);
  const isDeadRef    = useRef(isDead);

  useEffect(() => { isDeadRef.current = isDead; }, [isDead]);

  useEffect(() => {
    camera.rotation.order = 'YXZ';
    const spawnY = worldManager.getTerrainHeight(8, 8) + 3;
    pos.current.set(8, spawnY, 8);
  }, [camera]);

  // Respawn trigger — reset position and vitals
  useEffect(() => {
    if (respawnTrigger === 0) return;
    const spawnY = worldManager.getTerrainHeight(8, 8) + 3;
    pos.current.set(8, spawnY, 8);
    vel.current.set(0, 0, 0);
    health.current = 20;
    hunger.current = 20;
    breakPos.current = null;
    breakStart.current = 0;
  }, [respawnTrigger]);

  useEffect(() => { hotbar.current = [...externalHotbar]; }, [externalHotbar]);
  useEffect(() => { slot.current = externalSlot; }, [externalSlot]);

  useEffect(() => {
    modeRef.current = mode;
    if (mode !== prevMode.current) {
      prevMode.current = mode;
      if (mode !== 'CREATIVE') flying.current = false;
    }
  }, [mode]);

  useEffect(() => {
    const el = gl.domElement;
    const lock = () => { if (document.pointerLockElement !== el && !isDeadRef.current) el.requestPointerLock?.(); };
    el.addEventListener('click', lock);
    return () => el.removeEventListener('click', lock);
  }, [gl.domElement]);

  useEffect(() => {
    const el = gl.domElement;
    const onMove = (e: MouseEvent) => {
      if (document.pointerLockElement !== el || isDeadRef.current) return;
      yaw.current   -= e.movementX * 0.002;
      pitch.current -= e.movementY * 0.002;
      pitch.current  = Math.max(-1.5, Math.min(1.5, pitch.current));
    };
    document.addEventListener('mousemove', onMove);
    return () => document.removeEventListener('mousemove', onMove);
  }, [gl]);

  useEffect(() => {
    const el = gl.domElement;
    const dn = (e: MouseEvent) => {
      if (document.pointerLockElement !== el) return;
      if (e.button === 0) { lmbDown.current = true; breakStart.current = 0; breakPos.current = null; }
      if (e.button === 2) rmbDown.current = true;
    };
    const up = (e: MouseEvent) => {
      if (e.button === 0) { lmbDown.current = false; breakStart.current = 0; breakPos.current = null; }
      if (e.button === 2) rmbDown.current = false;
    };
    const ctx = (e: Event) => e.preventDefault();
    document.addEventListener('mousedown', dn);
    document.addEventListener('mouseup', up);
    document.addEventListener('contextmenu', ctx);
    return () => {
      document.removeEventListener('mousedown', dn);
      document.removeEventListener('mouseup', up);
      document.removeEventListener('contextmenu', ctx);
    };
  }, [gl]);

  useEffect(() => {
    const dn = (e: KeyboardEvent) => {
      if (isDeadRef.current) return;
      const n = parseInt(e.code.replace('Digit',''));
      if (n >= 1 && n <= 9) slot.current = n - 1;
      if (e.code === 'Space' && modeRef.current === 'CREATIVE') {
        const now = Date.now();
        if (now - spaceLastTap.current < 350) flying.current = !flying.current;
        spaceLastTap.current = now;
      }
    };
    const wh = (e: WheelEvent) => {
      if (isDeadRef.current) return;
      slot.current = ((slot.current + (e.deltaY > 0 ? 1 : -1)) + 9) % 9;
    };
    window.addEventListener('keydown', dn);
    window.addEventListener('wheel', wh);
    return () => { window.removeEventListener('keydown', dn); window.removeEventListener('wheel', wh); };
  }, []);

  useFrame((_, delta) => {
    if (isDeadRef.current) return;

    const dt = Math.min(delta, 0.05);
    const k  = getKeys();
    const t  = touchRef.current;
    const locked  = document.pointerLockElement === gl.domElement;
    const curMode = modeRef.current;

    if (t.lookDx !== 0 || t.lookDy !== 0) {
      yaw.current   -= t.lookDx * 0.004;
      pitch.current -= t.lookDy * 0.004;
      pitch.current  = Math.max(-1.5, Math.min(1.5, pitch.current));
      t.lookDx = 0; t.lookDy = 0;
    }

    if (t.toggleMode && !prevToggle.current) {
      setMode(curMode === 'CREATIVE' ? 'SURVIVAL' : 'CREATIVE');
    }
    prevToggle.current = t.toggleMode;

    const isFlying = flying.current && curMode === 'CREATIVE';
    const spd = isFlying ? FLY_SPEED : (curMode === 'CREATIVE' ? CREATIVE_SPEED : SPEED);
    const sinY = Math.sin(yaw.current), cosY = Math.cos(yaw.current);

    const fwd = k.forward || false, bk = k.back || false;
    const lft = k.left    || false, rgt = k.right || false;
    const jmp = k.jump || t.jump;

    let mx = 0, mz = 0;
    if (fwd) { mx -= sinY; mz -= cosY; }
    if (bk)  { mx += sinY; mz += cosY; }
    if (lft) { mx -= cosY; mz += sinY; }
    if (rgt) { mx += cosY; mz -= sinY; }
    if (t.dx !== 0 || t.dz !== 0) {
      mx = sinY * t.dz + cosY * t.dx;
      mz = cosY * t.dz - sinY * t.dx;
    }
    const ml = Math.sqrt(mx*mx + mz*mz);
    if (ml > 0) { mx /= ml; mz /= ml; }

    vel.current.x = mx * spd;
    vel.current.z = mz * spd;

    if (isFlying) {
      vel.current.y = 0;
      if (jmp)                  vel.current.y =  FLY_SPEED;
      if (k.sneak || t.flyDown) vel.current.y = -FLY_SPEED;
    } else {
      if (jmp && grounded.current) { vel.current.y = JUMP_FORCE; grounded.current = false; }
      vel.current.y -= GRAVITY * dt;
      vel.current.y  = Math.max(vel.current.y, -50);
    }

    const p = pos.current, v = vel.current;
    tmpPos.current.set(p.x + v.x * dt, p.y, p.z);
    if (!collidesAt(tmpPos.current)) p.x = tmpPos.current.x; else v.x = 0;

    tmpPos.current.set(p.x, p.y + v.y * dt, p.z);
    if (!collidesAt(tmpPos.current)) {
      p.y = tmpPos.current.y;
      if (!isFlying) grounded.current = false;
    } else {
      if (v.y < 0 && !isFlying) {
        grounded.current = true;
        if (curMode === 'SURVIVAL' && v.y < -12)
          health.current = Math.max(0, health.current - Math.floor((-v.y - 12) * 0.6));
      }
      v.y = 0;
    }

    tmpPos.current.set(p.x, p.y, p.z + v.z * dt);
    if (!collidesAt(tmpPos.current)) p.z = tmpPos.current.z; else v.z = 0;

    if (p.y < -10) {
      p.set(8, worldManager.getTerrainHeight(8, 8) + 3, 8);
      v.set(0, 0, 0);
      if (curMode === 'SURVIVAL') health.current = Math.max(0, health.current - 4);
    }

    camera.rotation.y = yaw.current;
    camera.rotation.x = pitch.current;
    eyePos.current.set(p.x, p.y + EYE_H, p.z);
    camera.position.copy(eyePos.current);
    playerChunkRef.current = { x: Math.floor(p.x / CHUNK_SIZE), z: Math.floor(p.z / CHUNK_SIZE) };

    const doBreak = lmbDown.current || t.doBreak;
    const doPlace = rmbDown.current || t.doPlace;

    if (locked || doBreak || doPlace) {
      camera.getWorldDirection(dir3.current);
      const reach = curMode === 'CREATIVE' ? MAX_REACH_CREATIVE : MAX_REACH_SURVIVAL;
      const ray   = castRay(eyePos.current, dir3.current, reach);

      const mobHit = doBreak
        ? raycastMobs(eyePos.current.x, eyePos.current.y, eyePos.current.z, dir3.current.x, dir3.current.y, dir3.current.z, reach)
        : null;

      if (mobHit && (!ray.hit || mobHit.dist < ray.dist)) {
        if (doBreak) {
          const now = Date.now();
          if (now - lastHit.current > 400) {
            damageMob(mobHit.id, curMode === 'CREATIVE' ? 10 : 5);
            lastHit.current = now;
          }
        }
      } else if (ray.hit && ray.hitPos) {
        if (doBreak) {
          const now = Date.now();
          const hp  = ray.hitPos;
          if (curMode === 'CREATIVE') {
            if (now - breakStart.current > 200) {
              worldManager.setBlock(hp.x, hp.y, hp.z, BlockType.AIR);
              breakStart.current = now;
            }
          } else {
            const samePos = breakPos.current?.equals(hp);
            if (!samePos) { breakPos.current = hp.clone(); breakStart.current = now; }
            if (now - breakStart.current >= BREAK_TIME_MS) {
              const blockType = worldManager.getBlock(hp.x, hp.y, hp.z);
              worldManager.setBlock(hp.x, hp.y, hp.z, BlockType.AIR);
              onBlockBreak(blockType);
              breakPos.current = null; breakStart.current = 0;
            }
          }
        } else { breakPos.current = null; breakStart.current = 0; }

        if (doPlace && ray.hitPos) {
          const hitBlock = worldManager.getBlock(ray.hitPos.x, ray.hitPos.y, ray.hitPos.z);
          const now = Date.now();
          if (hitBlock === BlockType.CHEST && onChestOpen) {
            if (now - lastPlace.current > 400) {
              onChestOpen(ray.hitPos.x, ray.hitPos.y, ray.hitPos.z);
              lastPlace.current = now;
            }
          } else if (ray.prevPos && now - lastPlace.current > 250) {
            const pp  = ray.prevPos;
            const blk = hotbar.current[slot.current];
            if (blk !== BlockType.AIR) {
              const canPl = curMode !== 'SURVIVAL' || canPlace(blk);
              if (canPl) {
                const hw = PLAYER_W / 2;
                const inside = pp.x >= Math.floor(p.x-hw) && pp.x <= Math.floor(p.x+hw-0.001)
                            && pp.y >= Math.floor(p.y)      && pp.y <= Math.floor(p.y+PLAYER_H-0.001)
                            && pp.z >= Math.floor(p.z-hw)   && pp.z <= Math.floor(p.z+hw-0.001);
                if (!inside) {
                  worldManager.setBlock(pp.x, pp.y, pp.z, blk);
                  lastPlace.current = now;
                  if (curMode === 'SURVIVAL') onBlockPlace(blk);
                }
              }
            }
          }
        }
      } else { breakPos.current = null; breakStart.current = 0; }
    }

    stateT.current += dt;
    if (stateT.current > 0.1) {
      stateT.current = 0;
      if (curMode === 'SURVIVAL') hunger.current = Math.max(0, hunger.current - 0.002);
      onStateChange({ health: health.current, hunger: hunger.current, hotbar: hotbar.current, selectedSlot: slot.current, pos: p.clone() });
    }
  });

  return null;
}

import { useState, useRef, useEffect, useCallback } from 'react';
import { Canvas } from '@react-three/fiber';
import { KeyboardControls } from '@react-three/drei';
import * as THREE from 'three';
import { BlockType, HOTBAR_CREATIVE } from './blocks';
import World from './World';
import Player from './Player';
import Animals from './Animals';
import Mobs from './Mobs';
import HUD from './HUD';
import TouchControls, { TouchState, createTouchState } from './TouchControls';
import Crafting from './Crafting';
import Inventory from './Inventory';
import ChestUI from './ChestUI';

export enum Controls {
  forward = 'forward',
  back    = 'back',
  left    = 'left',
  right   = 'right',
  jump    = 'jump',
  sneak   = 'sneak',
}

const KEY_MAP = [
  { name: Controls.forward, keys: ['ArrowUp',    'KeyW'] },
  { name: Controls.back,    keys: ['ArrowDown',  'KeyS'] },
  { name: Controls.left,    keys: ['ArrowLeft',  'KeyA'] },
  { name: Controls.right,   keys: ['ArrowRight', 'KeyD'] },
  { name: Controls.jump,    keys: ['Space'] },
  { name: Controls.sneak,   keys: ['ShiftLeft',  'ShiftRight'] },
];

const SURVIVAL_HOTBAR: BlockType[] = Array(9).fill(BlockType.AIR);
const CHEST_SLOTS = 27;

interface UIState {
  health:      number;
  hunger:      number;
  hotbar:      BlockType[];
  selectedSlot: number;
  pos:         { x: number; y: number; z: number };
  mode:        'CREATIVE' | 'SURVIVAL';
  counts:      Record<number, number>;
}

export default function Game() {
  const [started,       setStarted]       = useState(false);
  const [craftingOpen,  setCraftingOpen]  = useState(false);
  const [inventoryOpen, setInventoryOpen] = useState(false);
  const [dead,          setDead]          = useState(false);
  const [respawnTrigger, setRespawnTrigger] = useState(0);
  const [openChest,     setOpenChest]     = useState<{ x: number; y: number; z: number } | null>(null);

  const [uiState, setUiState] = useState<UIState>({
    health: 20, hunger: 20,
    hotbar: [...HOTBAR_CREATIVE], selectedSlot: 0,
    pos: { x: 0, y: 0, z: 0 },
    mode: 'CREATIVE',
    counts: {},
  });

  const playerChunkRef = useRef({ x: 0, z: 0 });
  const touchRef       = useRef<TouchState>(createTouchState());
  const playerPos      = useRef(new THREE.Vector3(8, 30, 8));
  const countsRef      = useRef<Record<number, number>>({});
  // Chest storage: "x,y,z" → BlockType[27]
  const chestsRef      = useRef<Map<string, BlockType[]>>(new Map());

  // Death detection
  useEffect(() => {
    if (uiState.mode === 'SURVIVAL' && uiState.health <= 0 && !dead && started) {
      setDead(true);
      setCraftingOpen(false);
      setInventoryOpen(false);
      setOpenChest(null);
    }
  }, [uiState.health, uiState.mode, dead, started]);

  // Keyboard shortcuts
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!started || dead) return;
      if (e.code === 'KeyE') { e.preventDefault(); setCraftingOpen(o => !o); setInventoryOpen(false); }
      if (e.code === 'KeyI') { e.preventDefault(); setInventoryOpen(o => !o); setCraftingOpen(false); }
      if (e.code === 'Escape') { setCraftingOpen(false); setInventoryOpen(false); setOpenChest(null); }
      if (e.code === 'Tab') {
        e.preventDefault();
        countsRef.current = {};
        setUiState(prev => {
          const newMode = prev.mode === 'CREATIVE' ? 'SURVIVAL' : 'CREATIVE';
          return { ...prev, mode: newMode, hotbar: newMode === 'CREATIVE' ? [...HOTBAR_CREATIVE] : [...SURVIVAL_HOTBAR], counts: {} };
        });
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [started, dead]);

  const handleStateChange = useCallback((s: {
    health: number; hunger: number;
    hotbar: BlockType[]; selectedSlot: number;
    pos: THREE.Vector3;
  }) => {
    playerPos.current.copy(s.pos);
    setUiState(prev => ({
      ...prev,
      health: s.health, hunger: s.hunger,
      hotbar: s.hotbar, selectedSlot: s.selectedSlot,
      pos: { x: s.pos.x, y: s.pos.y, z: s.pos.z },
    }));
  }, []);

  const handleMobDamage = useCallback((amount: number) => {
    setUiState(prev => {
      if (prev.mode !== 'SURVIVAL') return prev;
      return { ...prev, health: Math.max(0, prev.health - amount) };
    });
  }, []);

  const handleSetMode = useCallback((m: 'CREATIVE' | 'SURVIVAL') => {
    countsRef.current = {};
    setUiState(prev => ({
      ...prev, mode: m,
      hotbar: m === 'CREATIVE' ? [...HOTBAR_CREATIVE] : [...SURVIVAL_HOTBAR],
      counts: {},
    }));
  }, []);

  const canPlace = useCallback((type: BlockType) => (countsRef.current[type] || 0) > 0, []);

  const onBlockBreak = useCallback((type: BlockType) => {
    countsRef.current[type] = (countsRef.current[type] || 0) + 1;
    setUiState(prev => {
      const hotbar = [...prev.hotbar];
      if (!hotbar.includes(type)) {
        const ei = hotbar.indexOf(BlockType.AIR);
        if (ei !== -1) hotbar[ei] = type;
      }
      return { ...prev, hotbar, counts: { ...countsRef.current } };
    });
  }, []);

  const onBlockPlace = useCallback((type: BlockType) => {
    const newCnt = Math.max(0, (countsRef.current[type] || 0) - 1);
    countsRef.current[type] = newCnt;
    setUiState(prev => {
      const hotbar = [...prev.hotbar];
      if (newCnt === 0) {
        const i = hotbar.indexOf(type);
        if (i !== -1) hotbar[i] = BlockType.AIR;
      }
      return { ...prev, hotbar, counts: { ...countsRef.current } };
    });
  }, []);

  const handleSlotSelect = useCallback((i: number) => {
    setUiState(prev => ({ ...prev, selectedSlot: i }));
  }, []);

  const handleCraft = useCallback((result: BlockType, count: number, consume: { type: BlockType; count: number }[]) => {
    consume.forEach(ing => {
      countsRef.current[ing.type] = Math.max(0, (countsRef.current[ing.type] || 0) - ing.count);
      if (countsRef.current[ing.type] === 0) delete countsRef.current[ing.type];
    });
    countsRef.current[result] = (countsRef.current[result] || 0) + count;
    setUiState(prev => {
      const hotbar = [...prev.hotbar];
      consume.forEach(ing => {
        if ((countsRef.current[ing.type] || 0) === 0) {
          const idx = hotbar.indexOf(ing.type);
          if (idx !== -1) hotbar[idx] = BlockType.AIR;
        }
      });
      if (!hotbar.includes(result)) {
        const ei = hotbar.indexOf(BlockType.AIR);
        if (ei !== -1) hotbar[ei] = result;
      }
      return { ...prev, hotbar, counts: { ...countsRef.current } };
    });
  }, []);

  const handleInventoryAssign = useCallback((slotIdx: number, type: BlockType) => {
    setUiState(prev => {
      const hotbar = [...prev.hotbar];
      hotbar[slotIdx] = type;
      return { ...prev, hotbar, selectedSlot: slotIdx };
    });
  }, []);

  // Chest interaction
  const handleChestOpen = useCallback((x: number, y: number, z: number) => {
    const key = `${x},${y},${z}`;
    if (!chestsRef.current.has(key)) {
      chestsRef.current.set(key, Array(CHEST_SLOTS).fill(BlockType.AIR));
    }
    setOpenChest({ x, y, z });
    setCraftingOpen(false);
    setInventoryOpen(false);
  }, []);

  const handleChestChange = useCallback((newContents: BlockType[], newCounts: Record<number, number>) => {
    if (!openChest) return;
    const key = `${openChest.x},${openChest.y},${openChest.z}`;
    chestsRef.current.set(key, newContents);
    countsRef.current = { ...newCounts };
    setUiState(prev => ({ ...prev, counts: { ...newCounts } }));
  }, [openChest]);

  // Respawn
  const handleRespawn = useCallback(() => {
    setDead(false);
    setRespawnTrigger(t => t + 1);
    setUiState(prev => ({
      ...prev,
      health: 20, hunger: 20,
      hotbar: [...SURVIVAL_HOTBAR], counts: {},
    }));
    countsRef.current = {};
  }, []);

  const { mode, hotbar, selectedSlot, health, hunger, pos, counts } = uiState;

  const chestContents = openChest
    ? (chestsRef.current.get(`${openChest.x},${openChest.y},${openChest.z}`) ?? Array(CHEST_SLOTS).fill(BlockType.AIR))
    : null;

  return (
    <div style={{ width:'100vw', height:'100vh', overflow:'hidden', background:'#000', position:'relative' }}>

      {/* ── Start screen ─────────────────────────────────────── */}
      {!started && (
        <div onClick={() => setStarted(true)} style={{
          position:'absolute', inset:0, zIndex:100,
          background:'linear-gradient(180deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
          display:'flex', alignItems:'center', justifyContent:'center',
          flexDirection:'column', color:'#fff', cursor:'pointer',
          fontFamily:'"Courier New", monospace',
        }}>
          <div style={{ fontSize:52, fontWeight:'bold', color:'#5cb85c', textShadow:'0 0 20px rgba(92,184,92,0.6)', letterSpacing:4, marginBottom:8 }}>
            VoxelCraft
          </div>
          <div style={{ fontSize:13, color:'#aaa', marginBottom:40, letterSpacing:1 }}>
            226 Blocks · 10 Biomes · Crafting · Mobs · Pixel Textures
          </div>
          <div style={{ background:'rgba(92,184,92,0.2)', border:'2px solid #5cb85c', borderRadius:8, padding:'12px 32px', fontSize:18, color:'#5cb85c', letterSpacing:2 }}>
            ▶  CLICK TO PLAY
          </div>
          <div style={{ marginTop:40, fontSize:11, color:'rgba(255,255,255,0.4)', lineHeight:2, textAlign:'center' }}>
            WASD — Move &nbsp;|&nbsp; SPACE — Jump &nbsp;|&nbsp; SHIFT — Fly Down<br/>
            LMB — Break &nbsp;|&nbsp; RMB — Place / Open Chest &nbsp;|&nbsp; 1–9 — Hotbar<br/>
            E — Crafting &nbsp;|&nbsp; I — Inventory &nbsp;|&nbsp; Tab — Creative/Survival
          </div>
        </div>
      )}

      {/* ── Death screen ─────────────────────────────────────── */}
      {dead && (
        <div style={{
          position:'absolute', inset:0, zIndex:90,
          background:'rgba(80,0,0,0.82)',
          display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
          fontFamily:'"Courier New", monospace', color:'#fff',
        }}>
          <div style={{ fontSize:48, fontWeight:'bold', color:'#ff3333', textShadow:'0 0 30px #ff000088', letterSpacing:4, marginBottom:16 }}>
            YOU DIED
          </div>
          <div style={{ fontSize:14, color:'#cc9999', marginBottom:40 }}>
            Better luck next time, adventurer.
          </div>
          <div
            data-touch-btn="1"
            onTouchStart={e => { e.stopPropagation(); e.preventDefault(); handleRespawn(); }}
            onClick={handleRespawn}
            style={{
              background:'rgba(200,40,40,0.3)', border:'2px solid #ff4444',
              borderRadius:8, padding:'14px 48px', fontSize:20,
              color:'#ffaaaa', letterSpacing:3, cursor:'pointer',
              fontFamily:'"Courier New", monospace',
            }}
          >
            ⟳ RESPAWN
          </div>
        </div>
      )}

      {/* ── HUD ──────────────────────────────────────────────── */}
      {started && !dead && (
        <HUD
          mode={mode} health={health} hunger={hunger}
          hotbar={hotbar} counts={counts}
          selectedSlot={selectedSlot} pos={pos}
          onSlotSelect={handleSlotSelect}
          onOpenInventory={() => { setInventoryOpen(o => !o); setCraftingOpen(false); }}
        />
      )}

      {/* ── Top toolbar (mobile) ─────────────────────────────── */}
      {started && !dead && (
        <div style={{
          position:'absolute', top:14, left:'50%', transform:'translateX(-50%)',
          zIndex:30, display:'flex', gap:8, pointerEvents:'auto',
        }}>
          <div
            data-touch-btn="1"
            onTouchStart={e => { e.stopPropagation(); e.preventDefault(); setCraftingOpen(o => !o); setInventoryOpen(false); }}
            onClick={() => { setCraftingOpen(o => !o); setInventoryOpen(false); }}
            style={{
              padding:'6px 14px', borderRadius:16,
              background:'rgba(50,50,80,0.8)', border:'1px solid rgba(100,100,180,0.6)',
              color:'#aac', fontSize:11, fontWeight:700, cursor:'pointer', userSelect:'none',
            }}
          >⚒ Craft</div>
          <div
            data-touch-btn="1"
            onTouchStart={e => { e.stopPropagation(); e.preventDefault(); setInventoryOpen(o => !o); setCraftingOpen(false); }}
            onClick={() => { setInventoryOpen(o => !o); setCraftingOpen(false); }}
            style={{
              padding:'6px 14px', borderRadius:16,
              background:'rgba(30,60,80,0.8)', border:'1px solid rgba(68,136,204,0.6)',
              color:'#7ac', fontSize:11, fontWeight:700, cursor:'pointer', userSelect:'none',
            }}
          >📦 Bag</div>
        </div>
      )}

      {/* ── Modals ───────────────────────────────────────────── */}
      {craftingOpen && (
        <Crafting
          counts={mode === 'CREATIVE'
            ? (() => { const c: Record<number,number> = {}; for (let i=1;i<=225;i++) c[i]=99; return c; })()
            : counts}
          onCraft={handleCraft}
          onClose={() => setCraftingOpen(false)}
        />
      )}
      {inventoryOpen && (
        <Inventory
          mode={mode} counts={counts} hotbar={hotbar}
          selectedSlot={selectedSlot}
          onAssign={handleInventoryAssign}
          onClose={() => setInventoryOpen(false)}
        />
      )}
      {openChest && chestContents && (
        <ChestUI
          contents={chestContents}
          counts={mode === 'CREATIVE'
            ? (() => { const c: Record<number,number> = {}; for (let i=1;i<=225;i++) c[i]=99; return c; })()
            : counts}
          onContentsChange={handleChestChange}
          onClose={() => setOpenChest(null)}
        />
      )}

      {/* ── Touch controls ───────────────────────────────────── */}
      {started && <TouchControls stateRef={touchRef} />}

      {/* ── 3D Canvas ────────────────────────────────────────── */}
      <KeyboardControls map={KEY_MAP}>
        <Canvas
          camera={{ fov: 75, near: 0.05, far: 220 }}
          gl={{ antialias: false }}
          style={{ width:'100%', height:'100%' }}
        >
          <color attach="background" args={['#87CEEB']} />
          <fog attach="fog" args={['#aadcf0', 50, 110]} />
          <ambientLight intensity={0.45} />
          <directionalLight position={[50, 100, 30]} intensity={1.2} />

          <World playerChunkRef={playerChunkRef} />
          <Animals />

          {started && (
            <>
              <Mobs playerPos={playerPos.current} onPlayerDamage={handleMobDamage} />
              <Player
                mode={mode}
                setMode={handleSetMode}
                playerChunkRef={playerChunkRef}
                onStateChange={handleStateChange}
                touchRef={touchRef}
                externalSlot={selectedSlot}
                externalHotbar={hotbar}
                canPlace={canPlace}
                onBlockBreak={onBlockBreak}
                onBlockPlace={onBlockPlace}
                onChestOpen={handleChestOpen}
                isDead={dead}
                respawnTrigger={respawnTrigger}
              />
            </>
          )}
        </Canvas>
      </KeyboardControls>
    </div>
  );
}

